/* Ví dụ & cách dùng cho từ vựng HSK 2 (chỉ thêm từ chưa có trong examples-data.js) */
window.VOCAB_EXAMPLES = window.VOCAB_EXAMPLES || {};
(function(add){ Object.keys(add).forEach(function(k){ if (!window.VOCAB_EXAMPLES[k]) window.VOCAB_EXAMPLES[k] = add[k]; }); })({"觉得":{"en":"to think; to feel","exs":[{"use":"觉得 + câu: nêu cảm nhận/ý kiến cá nhân.","ex":"我觉得这个电影很好看。","py":"Wǒ juéde zhège diànyǐng hěn hǎokàn.","vi":"Tôi thấy bộ phim này rất hay.","en":"I think this movie is very good."},{"use":"觉得 + adj: cảm thấy (trạng thái).","ex":"今天我觉得很累。","py":"Jīntiān wǒ juéde hěn lèi.","vi":"Hôm nay tôi thấy rất mệt.","en":"I feel very tired today."},{"use":"Hỏi ý kiến: 你觉得……？","ex":"你觉得这件衣服怎么样？","py":"Nǐ juéde zhè jiàn yīfu zěnmeyàng?","vi":"Bạn thấy bộ đồ này thế nào?","en":"What do you think of this outfit?"}]},"旅游":{"en":"to travel; to take a trip","exs":[{"use":"旅游 làm động từ: đi du lịch.","ex":"我们想去北京旅游。","py":"Wǒmen xiǎng qù Běijīng lǚyóu.","vi":"Chúng tôi muốn đi Bắc Kinh du lịch.","en":"We want to travel to Beijing."},{"use":"去 + nơi + 旅游.","ex":"他每年夏天都去海边旅游。","py":"Tā měi nián xiàtiān dōu qù hǎibiān lǚyóu.","vi":"Mùa hè nào anh ấy cũng đi biển du lịch.","en":"He goes to the seaside every summer."},{"use":"Cũng có thể dùng như danh từ: 旅游 + 的 + N.","ex":"九月是旅游的好时间。","py":"Jiǔ yuè shì lǚyóu de hǎo shíjiān.","vi":"Tháng chín là thời điểm tốt để du lịch.","en":"September is a good time to travel."}]},"它":{"en":"it","exs":[{"use":"Đại từ ngôi thứ ba chỉ vật hoặc con vật.","ex":"这是我的猫，它很可爱。","py":"Zhè shì wǒ de māo, tā hěn kě'ài.","vi":"Đây là mèo của tôi, nó rất dễ thương.","en":"This is my cat; it is very cute."},{"use":"Làm tân ngữ: V + 它.","ex":"这本书很好，你看看它吧。","py":"Zhè běn shū hěn hǎo, nǐ kànkan tā ba.","vi":"Quyển sách này hay lắm, bạn đọc thử đi.","en":"This book is good, give it a try."},{"use":"Không dùng 它 để chỉ người.","ex":"小狗饿了，快给它吃的。","py":"Xiǎogǒu è le, kuài gěi tā chī de.","vi":"Chó con đói rồi, mau cho nó ăn đi.","en":"The puppy is hungry, feed it quickly."}]},"踢足球":{"en":"to play football (soccer)","exs":[{"use":"踢 + 足球: đá bóng, chỉ dùng cho bóng đá.","ex":"他喜欢踢足球。","py":"Tā xǐhuan tī zúqiú.","vi":"Anh ấy thích đá bóng.","en":"He likes playing football."},{"use":"去 + 踢足球: đi đá bóng.","ex":"下午我们去踢足球吧。","py":"Xiàwǔ wǒmen qù tī zúqiú ba.","vi":"Chiều nay chúng ta đi đá bóng nhé.","en":"Let's go play football this afternoon."},{"use":"跟 + người + 一起踢足球.","ex":"我常跟同学一起踢足球。","py":"Wǒ cháng gēn tóngxué yìqǐ tī zúqiú.","vi":"Tôi hay đá bóng cùng bạn học.","en":"I often play football with classmates."}]},"为什么":{"en":"why","exs":[{"use":"为什么 + động từ/câu: hỏi lý do.","ex":"你为什么不去？","py":"Nǐ wèi shénme bú qù?","vi":"Sao bạn không đi?","en":"Why aren't you going?"},{"use":"Đứng trước động từ hoặc đầu câu.","ex":"为什么今天这么冷？","py":"Wèi shénme jīntiān zhème lěng?","vi":"Tại sao hôm nay lạnh thế?","en":"Why is it so cold today?"},{"use":"Trả lời thường bắt đầu bằng 因为.","ex":"他为什么没来？因为他生病了。","py":"Tā wèi shénme méi lái? Yīnwèi tā shēng bìng le.","vi":"Sao anh ấy không đến? Vì anh ấy bị ốm.","en":"Why didn't he come? Because he is sick."}]},"新":{"en":"new","exs":[{"use":"新 + danh từ: cái mới.","ex":"我买了一部新手机。","py":"Wǒ mǎi le yí bù xīn shǒujī.","vi":"Tôi mua một chiếc điện thoại mới.","en":"I bought a new phone."},{"use":"Làm vị ngữ: 很新.","ex":"这件衣服很新。","py":"Zhè jiàn yīfu hěn xīn.","vi":"Bộ đồ này còn rất mới.","en":"This piece of clothing is quite new."},{"use":"新 + 同学/老师: người mới.","ex":"我们班来了一个新同学。","py":"Wǒmen bān lái le yí ge xīn tóngxué.","vi":"Lớp chúng tôi có thêm một bạn mới.","en":"A new classmate joined our class."}]},"眼睛":{"en":"eye","exs":[{"use":"Bộ phận cơ thể; lượng từ: 一双眼睛.","ex":"她的眼睛又大又黑。","py":"Tā de yǎnjing yòu dà yòu hēi.","vi":"Mắt cô ấy vừa to vừa đen.","en":"Her eyes are big and dark."},{"use":"眼睛 + 不舒服/疼: mắt khó chịu/đau.","ex":"看书太久，我的眼睛很累。","py":"Kàn shū tài jiǔ, wǒ de yǎnjing hěn lèi.","vi":"Đọc sách quá lâu nên mắt tôi mỏi.","en":"After reading for so long, my eyes are tired."},{"use":"闭上/睁开 + 眼睛.","ex":"请闭上眼睛，想一想。","py":"Qǐng bì shàng yǎnjing, xiǎng yi xiǎng.","vi":"Xin hãy nhắm mắt lại và nghĩ thử.","en":"Please close your eyes and think."}]},"要":{"en":"to want to; will; need to","exs":[{"use":"要 + động từ: muốn làm gì.","ex":"我要去图书馆。","py":"Wǒ yào qù túshūguǎn.","vi":"Tôi muốn đi thư viện.","en":"I want to go to the library."},{"use":"要 + động từ: dự định, sắp làm (tương lai gần).","ex":"明天我要早起。","py":"Míngtiān wǒ yào zǎo qǐ.","vi":"Mai tôi phải dậy sớm.","en":"I will get up early tomorrow."},{"use":"Phủ định thường dùng 不想 (không muốn), 不要 là \"đừng\".","ex":"我不想去，你要去吗？","py":"Wǒ bù xiǎng qù, nǐ yào qù ma?","vi":"Tôi không muốn đi, bạn muốn đi không?","en":"I don't want to go; do you?"}]},"也":{"en":"also; too","exs":[{"use":"也 đứng trước động từ/tính từ, sau chủ ngữ.","ex":"我也是学生。","py":"Wǒ yě shì xuésheng.","vi":"Tôi cũng là học sinh.","en":"I am a student too."},{"use":"Khi có 都: 也都 (cũng đều).","ex":"他们也都喜欢运动。","py":"Tāmen yě dōu xǐhuan yùndòng.","vi":"Họ cũng đều thích thể thao.","en":"They all like sports too."},{"use":"Không đặt 也 trước chủ ngữ.","ex":"你去，我也去。","py":"Nǐ qù, wǒ yě qù.","vi":"Bạn đi thì tôi cũng đi.","en":"If you go, I'll go too."}]},"一起":{"en":"together","exs":[{"use":"一起 + động từ: cùng làm.","ex":"我们一起去吧。","py":"Wǒmen yìqǐ qù ba.","vi":"Chúng ta cùng đi nhé.","en":"Let's go together."},{"use":"跟 + người + 一起 + V.","ex":"我跟朋友一起看电影。","py":"Wǒ gēn péngyou yìqǐ kàn diànyǐng.","vi":"Tôi xem phim cùng bạn.","en":"I watch movies with my friend."},{"use":"Dùng để rủ rê, đề nghị.","ex":"一起吃饭，好吗？","py":"Yìqǐ chī fàn, hǎo ma?","vi":"Cùng đi ăn nhé, được không?","en":"Let's eat together, okay?"}]},"运动":{"en":"sport; to exercise","exs":[{"use":"Danh từ: môn thể thao.","ex":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?","en":"What sport do you like?"},{"use":"Động từ: tập thể dục.","ex":"他每天早上都运动。","py":"Tā měi tiān zǎoshang dōu yùndòng.","vi":"Sáng nào anh ấy cũng tập thể dục.","en":"He exercises every morning."},{"use":"运动 + 对身体好.","ex":"多运动对身体好。","py":"Duō yùndòng duì shēntǐ hǎo.","vi":"Vận động nhiều tốt cho sức khỏe.","en":"Exercising more is good for your health."}]},"最":{"en":"most; -est","exs":[{"use":"最 + tính từ/động từ tâm lý: mức cao nhất.","ex":"我最喜欢吃面条。","py":"Wǒ zuì xǐhuan chī miàntiáo.","vi":"Tôi thích ăn mì nhất.","en":"I like noodles the most."},{"use":"最 + adj.","ex":"这是最好的办法。","py":"Zhè shì zuì hǎo de bànfǎ.","vi":"Đây là cách tốt nhất.","en":"This is the best way."},{"use":"最 + 近/后: gần đây nhất / cuối cùng.","ex":"最近你忙不忙？","py":"Zuìjìn nǐ máng bu máng?","vi":"Dạo này bạn có bận không?","en":"Have you been busy lately?"}]},"花花":{"en":"Huahua (name of a cat)","exs":[{"use":"Tên riêng của mèo trong bài khóa.","ex":"花花是一只小猫。","py":"Huāhua shì yì zhī xiǎo māo.","vi":"Hoa Hoa là một chú mèo con.","en":"Huahua is a kitten."},{"use":"Tên thú cưng thường lặp âm.","ex":"花花喜欢睡觉。","py":"Huāhua xǐhuan shuì jiào.","vi":"Hoa Hoa thích ngủ.","en":"Huahua likes to sleep."},{"use":"Có thể thêm 小 phía trước để thân mật.","ex":"小花花，过来吃饭！","py":"Xiǎo Huāhua, guòlai chī fàn!","vi":"Hoa Hoa bé bỏng, lại ăn cơm nào!","en":"Little Huahua, come and eat!"}]},"高":{"en":"tall; high","exs":[{"use":"高 làm vị ngữ: chỉ chiều cao.","ex":"他很高。","py":"Tā hěn gāo.","vi":"Anh ấy rất cao.","en":"He is very tall."},{"use":"Hỏi chiều cao: 多高？","ex":"你多高？","py":"Nǐ duō gāo?","vi":"Bạn cao bao nhiêu?","en":"How tall are you?"},{"use":"高 cũng chỉ mức cao: 高兴, 高山.","ex":"那座山很高。","py":"Nà zuò shān hěn gāo.","vi":"Ngọn núi đó rất cao.","en":"That mountain is very high."}]},"忙":{"en":"busy","exs":[{"use":"很 + 忙: bận rộn.","ex":"我最近很忙。","py":"Wǒ zuìjìn hěn máng.","vi":"Dạo này tôi rất bận.","en":"I've been very busy lately."},{"use":"Câu hỏi: 忙不忙？","ex":"你今天忙不忙？","py":"Nǐ jīntiān máng bu máng?","vi":"Hôm nay bạn có bận không?","en":"Are you busy today?"},{"use":"忙 + 着 + V: bận làm gì.","ex":"妈妈忙着做饭。","py":"Māma mángzhe zuò fàn.","vi":"Mẹ đang bận nấu cơm.","en":"Mom is busy cooking."}]},"每":{"en":"every; each","exs":[{"use":"每 + lượng từ/danh từ: mỗi một.","ex":"每天我都喝牛奶。","py":"Měi tiān wǒ dōu hē niúnǎi.","vi":"Ngày nào tôi cũng uống sữa.","en":"I drink milk every day."},{"use":"每 + 个 + N + 都…: mỗi ... đều.","ex":"每个人都有手机。","py":"Měi ge rén dōu yǒu shǒujī.","vi":"Mỗi người đều có điện thoại.","en":"Everyone has a cell phone."},{"use":"每次: mỗi lần.","ex":"每次他都来得很早。","py":"Měi cì tā dōu lái de hěn zǎo.","vi":"Lần nào anh ấy cũng đến rất sớm.","en":"He always arrives early."}]},"跑步":{"en":"to run; to jog","exs":[{"use":"跑步 là động từ li hợp (跑 + 步).","ex":"我喜欢早上跑步。","py":"Wǒ xǐhuan zǎoshang pǎo bù.","vi":"Tôi thích chạy bộ buổi sáng.","en":"I like jogging in the morning."},{"use":"去 + 公园 + 跑步.","ex":"他每天去公园跑步。","py":"Tā měi tiān qù gōngyuán pǎo bù.","vi":"Mỗi ngày anh ấy ra công viên chạy bộ.","en":"He jogs in the park every day."},{"use":"Có thể chèn từ giữa: 跑了一个小时步.","ex":"我跑了半个小时步。","py":"Wǒ pǎo le bàn ge xiǎoshí bù.","vi":"Tôi đã chạy bộ nửa tiếng.","en":"I jogged for half an hour."}]},"起床":{"en":"to get up (out of bed)","exs":[{"use":"起床 là động từ li hợp.","ex":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐ chuáng.","vi":"Mỗi ngày tôi dậy lúc sáu giờ.","en":"I get up at six every day."},{"use":"起 + 得 + 早/晚: dậy sớm/muộn.","ex":"他今天起得很晚。","py":"Tā jīntiān qǐ de hěn wǎn.","vi":"Hôm nay anh ấy dậy rất muộn.","en":"He got up very late today."},{"use":"Mệnh lệnh: 快起床！","ex":"快起床，要迟到了！","py":"Kuài qǐ chuáng, yào chídào le!","vi":"Dậy mau, sắp muộn rồi!","en":"Get up, you'll be late!"}]},"身体":{"en":"body; health","exs":[{"use":"身体 + 好/不好: sức khỏe tốt/không tốt.","ex":"爷爷身体很好。","py":"Yéye shēntǐ hěn hǎo.","vi":"Ông nội sức khỏe rất tốt.","en":"Grandpa is in good health."},{"use":"身体 + 不舒服: người khó chịu.","ex":"我今天身体不舒服。","py":"Wǒ jīntiān shēntǐ bù shūfu.","vi":"Hôm nay tôi thấy trong người không khỏe.","en":"I don't feel well today."},{"use":"Lời chúc: 注意身体.","ex":"你要注意身体。","py":"Nǐ yào zhùyì shēntǐ.","vi":"Bạn nhớ giữ gìn sức khỏe.","en":"Take care of your health."}]},"生病":{"en":"to fall ill; to be sick","exs":[{"use":"生病 là động từ li hợp.","ex":"他生病了，没去上班。","py":"Tā shēng bìng le, méi qù shàng bān.","vi":"Anh ấy ốm nên không đi làm.","en":"He is sick and didn't go to work."},{"use":"生 + 了 + 病.","ex":"孩子昨天生了病。","py":"Háizi zuótiān shēng le bìng.","vi":"Hôm qua đứa bé bị ốm.","en":"The child got sick yesterday."},{"use":"生病 + 要 + 吃药/休息.","ex":"生病了要多休息。","py":"Shēng bìng le yào duō xiūxi.","vi":"Bị ốm thì nên nghỉ ngơi nhiều.","en":"When you're ill, rest more."}]},"时间":{"en":"time","exs":[{"use":"有/没有 + 时间: có/không có thời gian.","ex":"我今天没有时间。","py":"Wǒ jīntiān méiyǒu shíjiān.","vi":"Hôm nay tôi không có thời gian.","en":"I don't have time today."},{"use":"时间 + 太 + 短/长.","ex":"休息的时间太短了。","py":"Xiūxi de shíjiān tài duǎn le.","vi":"Thời gian nghỉ ngơi quá ngắn.","en":"The rest time is too short."},{"use":"Hỏi giờ: 现在是什么时间？","ex":"现在是什么时间？","py":"Xiànzài shì shénme shíjiān?","vi":"Bây giờ là mấy giờ?","en":"What time is it now?"}]},"休息":{"en":"to rest; to take a break","exs":[{"use":"休息 + 一下: nghỉ một chút.","ex":"我们休息一下吧。","py":"Wǒmen xiūxi yíxià ba.","vi":"Chúng ta nghỉ một lát nhé.","en":"Let's take a short break."},{"use":"好好 + 休息.","ex":"你太累了，好好休息吧。","py":"Nǐ tài lèi le, hǎohāo xiūxi ba.","vi":"Bạn mệt quá rồi, nghỉ ngơi cho tốt đi.","en":"You're too tired, get some good rest."},{"use":"休息 cũng chỉ ngày nghỉ: 休息日.","ex":"星期天我休息。","py":"Xīngqītiān wǒ xiūxi.","vi":"Chủ nhật tôi được nghỉ.","en":"I'm off on Sundays."}]},"药":{"en":"medicine; drug","exs":[{"use":"吃药: uống thuốc (dùng 吃, không dùng 喝 với viên).","ex":"你该吃药了。","py":"Nǐ gāi chī yào le.","vi":"Đến giờ bạn uống thuốc rồi.","en":"It's time for you to take your medicine."},{"use":"买药: mua thuốc.","ex":"请帮我去买药。","py":"Qǐng bāng wǒ qù mǎi yào.","vi":"Nhờ bạn đi mua thuốc giúp tôi.","en":"Please buy medicine for me."},{"use":"药 + 很苦: thuốc đắng.","ex":"这个药很苦。","py":"Zhège yào hěn kǔ.","vi":"Thuốc này rất đắng.","en":"This medicine is very bitter."}]},"早上":{"en":"morning","exs":[{"use":"早上 + giờ: sáng lúc mấy giờ.","ex":"我早上七点吃饭。","py":"Wǒ zǎoshang qī diǎn chī fàn.","vi":"Sáng tôi ăn cơm lúc bảy giờ.","en":"I eat at seven in the morning."},{"use":"每天早上: mỗi sáng.","ex":"每天早上我都喝一杯水。","py":"Měi tiān zǎoshang wǒ dōu hē yì bēi shuǐ.","vi":"Mỗi sáng tôi uống một cốc nước.","en":"I drink a glass of water every morning."},{"use":"Lời chào: 早上好.","ex":"老师，早上好！","py":"Lǎoshī, zǎoshang hǎo!","vi":"Chào thầy buổi sáng!","en":"Good morning, teacher!"}]},"知道":{"en":"to know","exs":[{"use":"知道 + câu/tân ngữ: biết một việc.","ex":"我知道你的名字。","py":"Wǒ zhīdào nǐ de míngzi.","vi":"Tôi biết tên bạn.","en":"I know your name."},{"use":"Phủ định: 不知道.","ex":"我不知道他在哪儿。","py":"Wǒ bù zhīdào tā zài nǎr.","vi":"Tôi không biết anh ấy ở đâu.","en":"I don't know where he is."},{"use":"Câu hỏi: 你知道……吗？","ex":"你知道他几岁吗？","py":"Nǐ zhīdào tā jǐ suì ma?","vi":"Bạn có biết anh ấy mấy tuổi không?","en":"Do you know how old he is?"}]},"出":{"en":"to go out; to come out","exs":[{"use":"出 + địa điểm: đi ra khỏi.","ex":"他八点出门。","py":"Tā bā diǎn chū mén.","vi":"Tám giờ anh ấy ra khỏi nhà.","en":"He leaves home at eight."},{"use":"出 + 来/去 (bổ ngữ xu hướng).","ex":"请你出来一下。","py":"Qǐng nǐ chūlai yíxià.","vi":"Mời bạn ra đây một chút.","en":"Please come out for a moment."},{"use":"出 + 国/院/去.","ex":"他明年想出国。","py":"Tā míngnián xiǎng chū guó.","vi":"Sang năm anh ấy muốn ra nước ngoài.","en":"He wants to go abroad next year."}]},"出院":{"en":"to leave hospital","exs":[{"use":"出院 là động từ li hợp, trái nghĩa 住院.","ex":"爸爸明天出院。","py":"Bàba míngtiān chū yuàn.","vi":"Ngày mai bố xuất viện.","en":"Dad leaves the hospital tomorrow."},{"use":"出院 + 以后: sau khi xuất viện.","ex":"出院以后要多休息。","py":"Chū yuàn yǐhòu yào duō xiūxi.","vi":"Sau khi xuất viện cần nghỉ ngơi nhiều.","en":"After leaving the hospital, rest a lot."},{"use":"已经 + 出院.","ex":"她已经出院了。","py":"Tā yǐjīng chū yuàn le.","vi":"Cô ấy đã xuất viện rồi.","en":"She has already been discharged."}]},"米":{"en":"meter","exs":[{"use":"Đơn vị chiều dài; cũng nghĩa là \"gạo\".","ex":"这张桌子一米长。","py":"Zhè zhāng zhuōzi yì mǐ cháng.","vi":"Cái bàn này dài một mét.","en":"This table is one meter long."},{"use":"Số + 米 + 高/长: chỉ chiều cao/dài.","ex":"他一米八高。","py":"Tā yì mǐ bā gāo.","vi":"Anh ấy cao một mét tám.","en":"He is 1.8 meters tall."},{"use":"米 còn là \"gạo\": 米饭.","ex":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","vi":"Tôi muốn ăn cơm.","en":"I want to eat rice."}]},"报纸":{"en":"newspaper","exs":[{"use":"Lượng từ: 一张/一份报纸.","ex":"爷爷每天看报纸。","py":"Yéye měi tiān kàn bàozhǐ.","vi":"Ông nội ngày nào cũng đọc báo.","en":"Grandpa reads the newspaper every day."},{"use":"买/看 + 报纸.","ex":"我去买一份报纸。","py":"Wǒ qù mǎi yí fèn bàozhǐ.","vi":"Tôi đi mua một tờ báo.","en":"I'm going to buy a newspaper."},{"use":"Vị trí: 在……上.","ex":"报纸在桌子上。","py":"Bàozhǐ zài zhuōzi shang.","vi":"Tờ báo ở trên bàn.","en":"The newspaper is on the table."}]},"房间":{"en":"room","exs":[{"use":"Lượng từ: 一个房间.","ex":"我的房间很干净。","py":"Wǒ de fángjiān hěn gānjìng.","vi":"Phòng của tôi rất sạch.","en":"My room is very clean."},{"use":"进/出 + 房间.","ex":"他进了房间，关上门。","py":"Tā jìn le fángjiān, guān shàng mén.","vi":"Anh ấy vào phòng rồi đóng cửa.","en":"He entered the room and closed the door."},{"use":"房间号: số phòng.","ex":"你的房间号是多少？","py":"Nǐ de fángjiān hào shì duōshao?","vi":"Số phòng của bạn là bao nhiêu?","en":"What's your room number?"}]},"红":{"en":"red","exs":[{"use":"红 + N: màu đỏ.","ex":"她穿着红裙子。","py":"Tā chuānzhe hóng qúnzi.","vi":"Cô ấy mặc váy đỏ.","en":"She is wearing a red skirt."},{"use":"红 làm vị ngữ: 很红.","ex":"苹果很红。","py":"Píngguǒ hěn hóng.","vi":"Quả táo rất đỏ.","en":"The apple is very red."},{"use":"红 + 的: cái màu đỏ.","ex":"我要红的，不要白的。","py":"Wǒ yào hóng de, bú yào bái de.","vi":"Tôi muốn cái đỏ, không lấy cái trắng.","en":"I want the red one, not the white one."}]},"牛奶":{"en":"milk","exs":[{"use":"喝 + 牛奶; lượng từ 一杯/一瓶.","ex":"我每天喝一杯牛奶。","py":"Wǒ měi tiān hē yì bēi niúnǎi.","vi":"Mỗi ngày tôi uống một cốc sữa.","en":"I drink a glass of milk every day."},{"use":"买牛奶.","ex":"冰箱里没有牛奶了。","py":"Bīngxiāng li méiyǒu niúnǎi le.","vi":"Trong tủ lạnh hết sữa rồi.","en":"There's no more milk in the fridge."},{"use":"牛奶 + 咖啡: sữa pha cà phê.","ex":"请给我一杯牛奶咖啡。","py":"Qǐng gěi wǒ yì bēi niúnǎi kāfēi.","vi":"Cho tôi một ly cà phê sữa.","en":"A latte, please."}]},"旁边":{"en":"beside; next to","exs":[{"use":"N + 旁边: bên cạnh vật gì.","ex":"银行在学校旁边。","py":"Yínháng zài xuéxiào pángbiān.","vi":"Ngân hàng ở cạnh trường.","en":"The bank is next to the school."},{"use":"在 + 旁边.","ex":"他坐在我旁边。","py":"Tā zuò zài wǒ pángbiān.","vi":"Anh ấy ngồi cạnh tôi.","en":"He sits next to me."},{"use":"旁边 + 的 + N.","ex":"旁边的房间是我的。","py":"Pángbiān de fángjiān shì wǒ de.","vi":"Phòng bên cạnh là của tôi.","en":"The room next door is mine."}]},"千":{"en":"thousand","exs":[{"use":"一千 = 1000; hàng nghìn dùng 千.","ex":"这本书一千块钱。","py":"Zhè běn shū yì qiān kuài qián.","vi":"Quyển sách này một nghìn tệ.","en":"This book costs a thousand yuan."},{"use":"两千 (không dùng 二千).","ex":"他有两千本书。","py":"Tā yǒu liǎng qiān běn shū.","vi":"Anh ấy có hai nghìn quyển sách.","en":"He has two thousand books."},{"use":"千 + 万: ngàn vạn / vô cùng.","ex":"这个城市有几千万人。","py":"Zhège chéngshì yǒu jǐ qiān wàn rén.","vi":"Thành phố này có vài chục triệu người.","en":"This city has tens of millions of people."}]},"手表":{"en":"wristwatch","exs":[{"use":"Lượng từ: 一块手表.","ex":"他有一块新手表。","py":"Tā yǒu yí kuài xīn shǒubiǎo.","vi":"Anh ấy có một chiếc đồng hồ mới.","en":"He has a new watch."},{"use":"戴 + 手表: đeo đồng hồ.","ex":"她手上戴着一块手表。","py":"Tā shǒu shang dàizhe yí kuài shǒubiǎo.","vi":"Trên tay cô ấy đeo một chiếc đồng hồ.","en":"She is wearing a watch."},{"use":"我的手表 + 快/慢了.","ex":"我的手表慢了五分钟。","py":"Wǒ de shǒubiǎo màn le wǔ fēnzhōng.","vi":"Đồng hồ của tôi chậm năm phút.","en":"My watch is five minutes slow."}]},"送":{"en":"to give (a gift); to send; to see off","exs":[{"use":"送 + người + vật: tặng ai cái gì.","ex":"我送他一本书。","py":"Wǒ sòng tā yì běn shū.","vi":"Tôi tặng anh ấy một quyển sách.","en":"I gave him a book."},{"use":"送 + 人 + 去/到 + nơi: đưa ai đến đâu.","ex":"我送你回家吧。","py":"Wǒ sòng nǐ huí jiā ba.","vi":"Để tôi đưa bạn về nhà.","en":"Let me take you home."},{"use":"送 + 礼物.","ex":"生日那天，朋友送了我一个礼物。","py":"Shēngrì nà tiān, péngyou sòng le wǒ yí ge lǐwù.","vi":"Hôm sinh nhật, bạn tặng tôi một món quà.","en":"On my birthday, a friend gave me a gift."}]},"颜色":{"en":"color","exs":[{"use":"什么颜色: màu gì.","ex":"你喜欢什么颜色？","py":"Nǐ xǐhuan shénme yánsè?","vi":"Bạn thích màu gì?","en":"What color do you like?"},{"use":"颜色 + 很 + adj.","ex":"这个颜色很好看。","py":"Zhège yánsè hěn hǎokàn.","vi":"Màu này rất đẹp.","en":"This color looks nice."},{"use":"换 + 颜色.","ex":"这件有别的颜色吗？","py":"Zhè jiàn yǒu bié de yánsè ma?","vi":"Cái này còn màu khác không?","en":"Does this come in other colors?"}]},"一下":{"en":"a little; a bit (soft tone)","exs":[{"use":"V + 一下: làm thử/làm nhanh, giọng nhẹ nhàng.","ex":"请等一下。","py":"Qǐng děng yíxià.","vi":"Xin đợi một chút.","en":"Please wait a moment."},{"use":"Dùng khi nhờ vả lịch sự.","ex":"你帮我看一下这个字。","py":"Nǐ bāng wǒ kàn yíxià zhège zì.","vi":"Bạn xem giúp tôi chữ này một chút.","en":"Please take a look at this character for me."},{"use":"介绍一下: giới thiệu một chút.","ex":"我来介绍一下，这是我同学。","py":"Wǒ lái jièshào yíxià, zhè shì wǒ tóngxué.","vi":"Để tôi giới thiệu chút, đây là bạn học của tôi.","en":"Let me introduce: this is my classmate."}]},"丈夫":{"en":"husband","exs":[{"use":"我丈夫: chồng tôi.","ex":"她的丈夫是医生。","py":"Tā de zhàngfu shì yīshēng.","vi":"Chồng cô ấy là bác sĩ.","en":"Her husband is a doctor."},{"use":"丈夫 + 和 + 妻子.","ex":"丈夫和妻子一起去旅游。","py":"Zhàngfu hé qīzi yìqǐ qù lǚyóu.","vi":"Hai vợ chồng cùng đi du lịch.","en":"The husband and wife travel together."},{"use":"对 + 丈夫 + 很好.","ex":"她对丈夫很好。","py":"Tā duì zhàngfu hěn hǎo.","vi":"Cô ấy đối xử với chồng rất tốt.","en":"She treats her husband very well."}]},"真":{"en":"really; truly","exs":[{"use":"真 + adj: nhấn mạnh cảm thán.","ex":"今天真热！","py":"Jīntiān zhēn rè!","vi":"Hôm nay nóng thật!","en":"It's really hot today!"},{"use":"真 + 好/漂亮.","ex":"这个房间真漂亮。","py":"Zhège fángjiān zhēn piàoliang.","vi":"Căn phòng này đẹp thật.","en":"This room is really beautiful."},{"use":"真的吗？: thật không?","ex":"他考了第一，真的吗？","py":"Tā kǎo le dì yī, zhēn de ma?","vi":"Anh ấy đứng nhất à, thật không?","en":"He came first? Really?"}]},"左边":{"en":"left side","exs":[{"use":"N + 左边: bên trái của vật.","ex":"我家在学校左边。","py":"Wǒ jiā zài xuéxiào zuǒbian.","vi":"Nhà tôi ở bên trái trường.","en":"My home is to the left of the school."},{"use":"左边 + 的 + N.","ex":"左边的那个是我的。","py":"Zuǒbian de nàge shì wǒ de.","vi":"Cái bên trái là của tôi.","en":"The one on the left is mine."},{"use":"Đối lập 右边.","ex":"左边是书店，右边是银行。","py":"Zuǒbian shì shūdiàn, yòubian shì yínháng.","vi":"Bên trái là hiệu sách, bên phải là ngân hàng.","en":"The bookstore is on the left, the bank on the right."}]},"粉色":{"en":"pink","exs":[{"use":"粉色 + N: màu hồng.","ex":"她喜欢粉色的裙子。","py":"Tā xǐhuan fěnsè de qúnzi.","vi":"Cô ấy thích váy màu hồng.","en":"She likes pink skirts."},{"use":"粉色 + 的 + N.","ex":"这个粉色的包很可爱。","py":"Zhège fěnsè de bāo hěn kě'ài.","vi":"Chiếc túi màu hồng này rất đáng yêu.","en":"This pink bag is very cute."},{"use":"Hỏi màu: 粉色还是红色?","ex":"你要粉色还是红色的？","py":"Nǐ yào fěnsè háishi hóngsè de?","vi":"Bạn muốn cái màu hồng hay màu đỏ?","en":"Do you want the pink one or the red one?"}]},"粉":{"en":"pink (adj.); powder","exs":[{"use":"粉 làm tính từ: màu hồng.","ex":"她的衣服是粉的。","py":"Tā de yīfu shì fěn de.","vi":"Quần áo của cô ấy màu hồng.","en":"Her clothes are pink."},{"use":"粉红 : hồng phấn.","ex":"花是粉红的。","py":"Huā shì fěnhóng de.","vi":"Hoa màu hồng phấn.","en":"The flower is pink."},{"use":"粉 cũng là bột/miến: 米粉.","ex":"我想吃米粉。","py":"Wǒ xiǎng chī mǐfěn.","vi":"Tôi muốn ăn bún/phở.","en":"I want to eat rice noodles."}]},"红色":{"en":"red (color)","exs":[{"use":"红色 + 的 + N: đồ màu đỏ.","ex":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vi":"Cái màu đỏ bên trái là của tôi.","en":"The red one on the left is mine."},{"use":"红色 + 很 + 好看.","ex":"红色很好看。","py":"Hóngsè hěn hǎokàn.","vi":"Màu đỏ rất đẹp.","en":"Red looks great."},{"use":"喜欢 + 红色.","ex":"过年的时候，大家都喜欢红色。","py":"Guò nián de shíhou, dàjiā dōu xǐhuan hóngsè.","vi":"Dịp Tết mọi người đều thích màu đỏ.","en":"At the New Year, everyone likes red."}]},"长":{"en":"long; to grow; to develop","exs":[{"use":"长 (cháng) làm vị ngữ: dài.","ex":"这条路很长。","py":"Zhè tiáo lù hěn cháng.","vi":"Con đường này rất dài.","en":"This road is very long."},{"use":"长 + N: tóc dài, thời gian dài.","ex":"她有一头长头发。","py":"Tā yǒu yì tóu cháng tóufa.","vi":"Cô ấy có mái tóc dài.","en":"She has long hair."},{"use":"Hỏi độ dài: 多长？","ex":"这条河有多长？","py":"Zhè tiáo hé yǒu duō cháng?","vi":"Con sông này dài bao nhiêu?","en":"How long is this river?"},{"use":"长 (zhǎng): lớn lên.","ex":"孩子长得很快。","py":"Háizi zhǎng de hěn kuài.","vi":"Đứa trẻ lớn rất nhanh.","en":"The child grows quickly."},{"use":"长 + 得: trông như thế nào.","ex":"她长得很漂亮。","py":"Tā zhǎng de hěn piàoliang.","vi":"Cô ấy trông rất xinh.","en":"She is very pretty."},{"use":"长大: trưởng thành.","ex":"我长大以后想当医生。","py":"Wǒ zhǎng dà yǐhòu xiǎng dāng yīshēng.","vi":"Lớn lên tôi muốn làm bác sĩ.","en":"When I grow up I want to be a doctor."}]},"非常":{"en":"very; extremely","exs":[{"use":"非常 + adj/động từ tâm lý: mức độ cao.","ex":"今天非常热。","py":"Jīntiān fēicháng rè.","vi":"Hôm nay cực kỳ nóng.","en":"It's extremely hot today."},{"use":"非常 + 喜欢/感谢.","ex":"我非常喜欢这个地方。","py":"Wǒ fēicháng xǐhuan zhège dìfang.","vi":"Tôi rất thích nơi này.","en":"I like this place very much."},{"use":"Không dùng 很 cùng lúc.","ex":"他做得非常好。","py":"Tā zuò de fēicháng hǎo.","vi":"Anh ấy làm rất tốt.","en":"He did extremely well."}]},"给":{"en":"to give; to, for","exs":[{"use":"给 + người + vật: đưa cho ai cái gì.","ex":"他给我一本书。","py":"Tā gěi wǒ yì běn shū.","vi":"Anh ấy đưa cho tôi một quyển sách.","en":"He gave me a book."},{"use":"给 + người + V: làm gì cho ai (giới từ).","ex":"我给妈妈打电话。","py":"Wǒ gěi māma dǎ diànhuà.","vi":"Tôi gọi điện cho mẹ.","en":"I call my mom."},{"use":"V + 给 + người.","ex":"请把这个送给他。","py":"Qǐng bǎ zhège sòng gěi tā.","vi":"Xin hãy tặng cái này cho anh ấy.","en":"Please give this to him."}]},"介绍":{"en":"to introduce; to recommend","exs":[{"use":"介绍 + 人/事: giới thiệu ai/việc gì.","ex":"我给你介绍一下我的朋友。","py":"Wǒ gěi nǐ jièshào yíxià wǒ de péngyou.","vi":"Tôi giới thiệu bạn tôi với bạn nhé.","en":"Let me introduce my friend to you."},{"use":"自我介绍: tự giới thiệu.","ex":"请你做一下自我介绍。","py":"Qǐng nǐ zuò yíxià zìwǒ jièshào.","vi":"Mời bạn tự giới thiệu một chút.","en":"Please introduce yourself."},{"use":"是……介绍的: được ai giới thiệu.","ex":"这个工作是他帮我介绍的。","py":"Zhège gōngzuò shì tā bāng wǒ jièshào de.","vi":"Công việc này là anh ấy giới thiệu cho tôi.","en":"He recommended me for this job."}]},"开始":{"en":"to begin; to start","exs":[{"use":"开始 + V/N: bắt đầu làm gì.","ex":"我们开始上课吧。","py":"Wǒmen kāishǐ shàng kè ba.","vi":"Chúng ta bắt đầu vào học nhé.","en":"Let's start the class."},{"use":"N + 开始: việc gì bắt đầu.","ex":"电影八点开始。","py":"Diànyǐng bā diǎn kāishǐ.","vi":"Phim bắt đầu lúc tám giờ.","en":"The movie starts at eight."},{"use":"从……开始.","ex":"从明天开始，我每天跑步。","py":"Cóng míngtiān kāishǐ, wǒ měi tiān pǎo bù.","vi":"Từ ngày mai tôi sẽ chạy bộ mỗi ngày.","en":"Starting tomorrow, I'll jog every day."}]},"快乐":{"en":"happy; glad","exs":[{"use":"Dùng trong lời chúc: 生日快乐.","ex":"祝你生日快乐！","py":"Zhù nǐ shēngrì kuàilè!","vi":"Chúc bạn sinh nhật vui vẻ!","en":"Happy birthday!"},{"use":"快乐 + 的 + N.","ex":"我们度过了快乐的一天。","py":"Wǒmen dùguò le kuàilè de yì tiān.","vi":"Chúng tôi đã có một ngày vui vẻ.","en":"We had a happy day."},{"use":"很快乐: rất vui.","ex":"孩子们玩得很快乐。","py":"Háizimen wán de hěn kuàilè.","vi":"Bọn trẻ chơi rất vui.","en":"The children had a lot of fun."}]},"两":{"en":"two","exs":[{"use":"两 + lượng từ + N (không dùng 二 trước lượng từ).","ex":"我有两个哥哥。","py":"Wǒ yǒu liǎng ge gēge.","vi":"Tôi có hai anh trai.","en":"I have two older brothers."},{"use":"两点: hai giờ.","ex":"现在是两点。","py":"Xiànzài shì liǎng diǎn.","vi":"Bây giờ là hai giờ.","en":"It's two o'clock."},{"use":"一两 + N: một hai cái (ước lượng).","ex":"我再等一两天。","py":"Wǒ zài děng yì liǎng tiān.","vi":"Tôi đợi thêm một hai ngày.","en":"I'll wait another day or two."}]},"生日":{"en":"birthday","exs":[{"use":"过生日: tổ chức sinh nhật.","ex":"明天是我的生日。","py":"Míngtiān shì wǒ de shēngrì.","vi":"Ngày mai là sinh nhật tôi.","en":"Tomorrow is my birthday."},{"use":"生日 + 快乐.","ex":"生日快乐，这是给你的礼物。","py":"Shēngrì kuàilè, zhè shì gěi nǐ de lǐwù.","vi":"Chúc mừng sinh nhật, đây là quà cho bạn.","en":"Happy birthday, this gift is for you."},{"use":"你的生日是几月几号？","ex":"你的生日是几月几号？","py":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","vi":"Sinh nhật bạn là ngày mấy tháng mấy?","en":"When is your birthday?"}]},"晚上":{"en":"evening; night","exs":[{"use":"晚上 + giờ/V: buổi tối làm gì.","ex":"我晚上七点吃饭。","py":"Wǒ wǎnshang qī diǎn chī fàn.","vi":"Tối tôi ăn cơm lúc bảy giờ.","en":"I eat dinner at seven in the evening."},{"use":"今天/每天 + 晚上.","ex":"今天晚上你有空吗？","py":"Jīntiān wǎnshang nǐ yǒu kòng ma?","vi":"Tối nay bạn rảnh không?","en":"Are you free tonight?"},{"use":"晚上好: chào buổi tối.","ex":"大家晚上好！","py":"Dàjiā wǎnshang hǎo!","vi":"Chào mọi người buổi tối!","en":"Good evening, everyone!"}]},"问":{"en":"to ask","exs":[{"use":"问 + người + câu hỏi.","ex":"我想问你一个问题。","py":"Wǒ xiǎng wèn nǐ yí ge wèntí.","vi":"Tôi muốn hỏi bạn một câu.","en":"I'd like to ask you a question."},{"use":"问 + 人 + 好: gửi lời hỏi thăm.","ex":"请代我问你妈妈好。","py":"Qǐng dài wǒ wèn nǐ māma hǎo.","vi":"Cho tôi gửi lời hỏi thăm mẹ bạn.","en":"Please say hello to your mom for me."},{"use":"问 + 路.","ex":"我去问一下路。","py":"Wǒ qù wèn yíxià lù.","vi":"Tôi đi hỏi đường một chút.","en":"I'll go ask for directions."}]},"已经":{"en":"already","exs":[{"use":"已经 + V + 了: đã làm rồi.","ex":"我已经吃饭了。","py":"Wǒ yǐjīng chī fàn le.","vi":"Tôi đã ăn cơm rồi.","en":"I have already eaten."},{"use":"已经 + 时间 + 了.","ex":"已经十二点了，快睡觉吧。","py":"Yǐjīng shí'èr diǎn le, kuài shuì jiào ba.","vi":"Đã mười hai giờ rồi, mau ngủ đi.","en":"It's already midnight; go to bed."},{"use":"Phủ định: 还没……呢.","ex":"他已经走了，你别等了。","py":"Tā yǐjīng zǒu le, nǐ bié děng le.","vi":"Anh ấy đi rồi, bạn đừng đợi nữa.","en":"He has already left, don't wait."}]},"接":{"en":"to receive; to pick up","exs":[{"use":"接 + 电话: nghe điện thoại.","ex":"他正在接电话。","py":"Tā zhèngzài jiē diànhuà.","vi":"Anh ấy đang nghe điện thoại.","en":"He is answering a phone call."},{"use":"接 + người: đón ai.","ex":"我去机场接朋友。","py":"Wǒ qù jīchǎng jiē péngyou.","vi":"Tôi ra sân bay đón bạn.","en":"I'm going to the airport to pick up a friend."},{"use":"接 + 东西: đón lấy.","ex":"请接一下这个包。","py":"Qǐng jiē yíxià zhège bāo.","vi":"Làm ơn đỡ giúp cái túi này.","en":"Please take this bag."}]},"帮":{"en":"to help","exs":[{"use":"帮 + người + V: giúp ai làm gì.","ex":"你能帮我拿一下吗？","py":"Nǐ néng bāng wǒ ná yíxià ma?","vi":"Bạn có thể cầm giúp tôi một chút không?","en":"Can you hold this for me?"},{"use":"帮 + 忙: giúp đỡ (li hợp).","ex":"谢谢你帮我。","py":"Xièxie nǐ bāng wǒ.","vi":"Cảm ơn bạn đã giúp tôi.","en":"Thank you for helping me."},{"use":"是……帮我……的.","ex":"这个工作是朋友帮我找的。","py":"Zhège gōngzuò shì péngyou bāng wǒ zhǎo de.","vi":"Công việc này là bạn giúp tôi tìm.","en":"A friend helped me find this job."}]},"吧":{"en":"particle for suggestion or request","exs":[{"use":"Cuối câu: đề nghị, nhờ vả, mệnh lệnh nhẹ.","ex":"就买这件吧。","py":"Jiù mǎi zhè jiàn ba.","vi":"Mua cái này đi.","en":"Let's just buy this one."},{"use":"Dùng để suy đoán nhẹ.","ex":"你是新同学吧？","py":"Nǐ shì xīn tóngxué ba?","vi":"Bạn là học sinh mới phải không?","en":"You're the new student, right?"},{"use":"Rủ rê cùng làm.","ex":"我们走吧。","py":"Wǒmen zǒu ba.","vi":"Chúng ta đi thôi.","en":"Let's go."}]},"对":{"en":"to, towards; correct","exs":[{"use":"对 + người + V/adj: đối với ai.","ex":"他对我很好。","py":"Tā duì wǒ hěn hǎo.","vi":"Anh ấy rất tốt với tôi.","en":"He is very kind to me."},{"use":"对 + 事 + 感兴趣.","ex":"我对音乐很感兴趣。","py":"Wǒ duì yīnyuè hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với âm nhạc.","en":"I'm very interested in music."},{"use":"对 làm tính từ: đúng.","ex":"你说得对。","py":"Nǐ shuō de duì.","vi":"Bạn nói đúng.","en":"You're right."}]},"还":{"en":"still; fairly","exs":[{"use":"还 + V: vẫn còn.","ex":"他还在睡觉。","py":"Tā hái zài shuì jiào.","vi":"Anh ấy vẫn đang ngủ.","en":"He is still sleeping."},{"use":"还 + adj: tạm được, khá.","ex":"这家饭馆还可以。","py":"Zhè jiā fànguǎn hái kěyǐ.","vi":"Quán ăn này cũng được.","en":"This restaurant is not bad."},{"use":"还 + 有: còn có thêm.","ex":"除了面条，还有米饭。","py":"Chúle miàntiáo, hái yǒu mǐfàn.","vi":"Ngoài mì còn có cơm.","en":"Besides noodles, there is also rice."}]},"件":{"en":"measure word for clothes, matters","exs":[{"use":"一件 + 衣服/事.","ex":"我买了一件衣服。","py":"Wǒ mǎi le yí jiàn yīfu.","vi":"Tôi mua một bộ đồ.","en":"I bought a piece of clothing."},{"use":"一件事: một việc.","ex":"我有一件事想问你。","py":"Wǒ yǒu yí jiàn shì xiǎng wèn nǐ.","vi":"Tôi có việc muốn hỏi bạn.","en":"I have something to ask you."},{"use":"这/那件.","ex":"那件衣服太贵了。","py":"Nà jiàn yīfu tài guì le.","vi":"Bộ đồ đó đắt quá.","en":"That piece of clothing is too expensive."}]},"就":{"en":"then; right away; only","exs":[{"use":"就 + V: nhấn mạnh quyết định/nhanh.","ex":"我们现在就走。","py":"Wǒmen xiànzài jiù zǒu.","vi":"Chúng ta đi ngay bây giờ.","en":"We'll leave right now."},{"use":"一……就……: hễ … là …","ex":"他一回家就看电视。","py":"Tā yì huí jiā jiù kàn diànshì.","vi":"Anh ấy hễ về nhà là xem tivi.","en":"As soon as he gets home he watches TV."},{"use":"就 + 数量: chỉ có (ít).","ex":"教室里就一个人。","py":"Jiàoshì li jiù yí ge rén.","vi":"Trong phòng học chỉ có một người.","en":"There's only one person in the classroom."}]},"咖啡":{"en":"coffee","exs":[{"use":"喝 + 咖啡; lượng từ 一杯.","ex":"我想喝一杯咖啡。","py":"Wǒ xiǎng hē yì bēi kāfēi.","vi":"Tôi muốn uống một ly cà phê.","en":"I'd like a cup of coffee."},{"use":"咖啡 + 店/馆: quán cà phê.","ex":"我们去咖啡店坐一会儿吧。","py":"Wǒmen qù kāfēidiàn zuò yíhuìr ba.","vi":"Mình ra quán cà phê ngồi một lát nhé.","en":"Let's sit in a coffee shop for a while."},{"use":"咖啡 + 太 + 苦.","ex":"这杯咖啡太苦了。","py":"Zhè bēi kāfēi tài kǔ le.","vi":"Ly cà phê này đắng quá.","en":"This coffee is too bitter."}]},"考试":{"en":"test; exam","exs":[{"use":"Danh từ và động từ li hợp.","ex":"明天有汉语考试。","py":"Míngtiān yǒu Hànyǔ kǎoshì.","vi":"Ngày mai có bài thi tiếng Hán.","en":"There is a Chinese exam tomorrow."},{"use":"参加 + 考试.","ex":"她要参加HSK考试。","py":"Tā yào cānjiā HSK kǎoshì.","vi":"Cô ấy sẽ dự thi HSK.","en":"She will take the HSK exam."},{"use":"考试 + 通过/没通过.","ex":"他考试考得很好。","py":"Tā kǎoshì kǎo de hěn hǎo.","vi":"Anh ấy thi rất tốt.","en":"He did very well on the exam."}]},"可以":{"en":"not bad; may, can","exs":[{"use":"还可以: cũng được, tạm ổn.","ex":"这个菜还可以。","py":"Zhège cài hái kěyǐ.","vi":"Món này cũng tạm được.","en":"This dish is okay."},{"use":"可以 + V: được phép.","ex":"这里可以坐吗？","py":"Zhèlǐ kěyǐ zuò ma?","vi":"Ngồi đây được không?","en":"May I sit here?"},{"use":"可以 + V: có thể (năng lực).","ex":"你可以用我的手机。","py":"Nǐ kěyǐ yòng wǒ de shǒujī.","vi":"Bạn có thể dùng điện thoại của tôi.","en":"You can use my phone."}]},"意思":{"en":"meaning","exs":[{"use":"什么意思: nghĩa là gì.","ex":"这个词是什么意思？","py":"Zhège cí shì shénme yìsi?","vi":"Từ này nghĩa là gì?","en":"What does this word mean?"},{"use":"有意思: thú vị.","ex":"这本书很有意思。","py":"Zhè běn shū hěn yǒu yìsi.","vi":"Quyển sách này rất thú vị.","en":"This book is very interesting."},{"use":"不好意思: xin lỗi, ngại quá.","ex":"不好意思，我来晚了。","py":"Bù hǎo yìsi, wǒ lái wǎn le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."}]},"鱼":{"en":"fish","exs":[{"use":"Lượng từ: 一条鱼.","ex":"我喜欢吃鱼。","py":"Wǒ xǐhuan chī yú.","vi":"Tôi thích ăn cá.","en":"I like eating fish."},{"use":"买鱼/做鱼.","ex":"妈妈今天做了一条鱼。","py":"Māma jīntiān zuò le yì tiáo yú.","vi":"Hôm nay mẹ nấu một con cá.","en":"Mom cooked a fish today."},{"use":"鱼 + 在 + 水里.","ex":"水里有很多鱼。","py":"Shuǐ li yǒu hěn duō yú.","vi":"Trong nước có nhiều cá.","en":"There are many fish in the water."}]},"准备":{"en":"to prepare; to plan","exs":[{"use":"准备 + V: dự định làm gì.","ex":"我准备明天去买东西。","py":"Wǒ zhǔnbèi míngtiān qù mǎi dōngxi.","vi":"Ngày mai tôi định đi mua đồ.","en":"I plan to go shopping tomorrow."},{"use":"准备 + N: chuẩn bị cái gì.","ex":"妈妈在准备晚饭。","py":"Māma zài zhǔnbèi wǎnfàn.","vi":"Mẹ đang chuẩn bị bữa tối.","en":"Mom is preparing dinner."},{"use":"准备好了吗？","ex":"你们准备好了吗？","py":"Nǐmen zhǔnbèi hǎo le ma?","vi":"Các bạn chuẩn bị xong chưa?","en":"Are you ready?"}]},"不错":{"en":"pretty good","exs":[{"use":"很不错: khá tốt.","ex":"这家饭馆很不错。","py":"Zhè jiā fànguǎn hěn búcuò.","vi":"Quán ăn này khá tốt.","en":"This restaurant is pretty good."},{"use":"不错 + 的 + N.","ex":"这是一个不错的主意。","py":"Zhè shì yí ge búcuò de zhǔyi.","vi":"Đây là một ý kiến không tồi.","en":"This is a pretty good idea."},{"use":"考得不错.","ex":"你这次考得不错。","py":"Nǐ zhè cì kǎo de búcuò.","vi":"Lần này bạn thi khá tốt.","en":"You did pretty well this time."}]},"外面":{"en":"outside","exs":[{"use":"在 + 外面: ở bên ngoài.","ex":"他在外面等你。","py":"Tā zài wàimian děng nǐ.","vi":"Anh ấy đang đợi bạn bên ngoài.","en":"He is waiting for you outside."},{"use":"外面 + 的 + N.","ex":"外面的天气很好。","py":"Wàimian de tiānqì hěn hǎo.","vi":"Thời tiết bên ngoài rất đẹp.","en":"The weather outside is nice."},{"use":"Trái nghĩa 里面.","ex":"外面很冷，里面很热。","py":"Wàimian hěn lěng, lǐmian hěn rè.","vi":"Bên ngoài lạnh, bên trong nóng.","en":"It's cold outside and hot inside."}]},"以后":{"en":"afterwards; later","exs":[{"use":"以后 đứng một mình: sau này.","ex":"以后我常来看你。","py":"Yǐhòu wǒ cháng lái kàn nǐ.","vi":"Sau này tôi sẽ thường đến thăm bạn.","en":"I'll visit you often from now on."},{"use":"……以后: sau khi ….","ex":"吃了饭以后，我们去散步。","py":"Chī le fàn yǐhòu, wǒmen qù sàn bù.","vi":"Sau khi ăn cơm chúng tôi đi dạo.","en":"After eating, we go for a walk."},{"use":"一小时以后: sau một giờ.","ex":"一个小时以后他才到。","py":"Yí ge xiǎoshí yǐhòu tā cái dào.","vi":"Một tiếng sau anh ấy mới đến.","en":"He only arrived an hour later."}]},"打篮球":{"en":"to play basketball","exs":[{"use":"打 + 篮球: chơi bóng rổ.","ex":"他每天下午打篮球。","py":"Tā měi tiān xiàwǔ dǎ lánqiú.","vi":"Chiều nào anh ấy cũng chơi bóng rổ.","en":"He plays basketball every afternoon."},{"use":"去 + 打篮球.","ex":"我们去打篮球吧。","py":"Wǒmen qù dǎ lánqiú ba.","vi":"Chúng ta đi chơi bóng rổ nhé.","en":"Let's go play basketball."},{"use":"会/喜欢 + 打篮球.","ex":"我哥哥很会打篮球。","py":"Wǒ gēge hěn huì dǎ lánqiú.","vi":"Anh trai tôi chơi bóng rổ rất giỏi.","en":"My brother is very good at basketball."}]},"姐姐":{"en":"elder sister","exs":[{"use":"Gọi chị ruột hoặc người lớn hơn.","ex":"我姐姐在北京工作。","py":"Wǒ jiějie zài Běijīng gōngzuò.","vi":"Chị tôi làm việc ở Bắc Kinh.","en":"My older sister works in Beijing."},{"use":"姐姐 + 比 + 我 + 大.","ex":"姐姐比我大两岁。","py":"Jiějie bǐ wǒ dà liǎng suì.","vi":"Chị hơn tôi hai tuổi.","en":"My sister is two years older than me."},{"use":"Đối lập 妹妹.","ex":"我有一个姐姐和一个妹妹。","py":"Wǒ yǒu yí ge jiějie hé yí ge mèimei.","vi":"Tôi có một chị gái và một em gái.","en":"I have an older sister and a younger sister."}]},"门":{"en":"door; gate","exs":[{"use":"开门/关门: mở/đóng cửa.","ex":"请把门关上。","py":"Qǐng bǎ mén guān shàng.","vi":"Làm ơn đóng cửa lại.","en":"Please close the door."},{"use":"门口: cửa ra vào.","ex":"他在门口等你。","py":"Tā zài ménkǒu děng nǐ.","vi":"Anh ấy đợi bạn ở cửa.","en":"He is waiting for you at the door."},{"use":"出门: ra khỏi nhà.","ex":"今天下雨，我不想出门。","py":"Jīntiān xià yǔ, wǒ bù xiǎng chū mén.","vi":"Hôm nay mưa, tôi không muốn ra ngoài.","en":"It's raining, I don't want to go out."}]},"面条":{"en":"noodles","exs":[{"use":"Lượng từ: 一碗面条.","ex":"我想吃一碗面条。","py":"Wǒ xiǎng chī yì wǎn miàntiáo.","vi":"Tôi muốn ăn một bát mì.","en":"I'd like a bowl of noodles."},{"use":"做面条.","ex":"妈妈做的面条很好吃。","py":"Māma zuò de miàntiáo hěn hǎochī.","vi":"Mì mẹ nấu rất ngon.","en":"The noodles Mom makes are delicious."},{"use":"羊肉面条: mì thịt dê.","ex":"他最喜欢羊肉面条。","py":"Tā zuì xǐhuan yángròu miàntiáo.","vi":"Anh ấy thích nhất mì thịt dê.","en":"He likes lamb noodles the most."}]},"所以":{"en":"so; therefore","exs":[{"use":"因为……，所以……: vì … nên ….","ex":"因为下雨，所以我没去。","py":"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.","vi":"Vì trời mưa nên tôi không đi.","en":"Because it rained, I didn't go."},{"use":"所以 mở đầu vế kết quả.","ex":"他生病了，所以没来上班。","py":"Tā shēng bìng le, suǒyǐ méi lái shàng bān.","vi":"Anh ấy ốm nên không đi làm.","en":"He was sick, so he didn't come to work."},{"use":"Có thể bỏ 因为.","ex":"我很忙，所以不能去。","py":"Wǒ hěn máng, suǒyǐ bù néng qù.","vi":"Tôi bận nên không thể đi.","en":"I'm busy, so I can't go."}]},"外":{"en":"outside; foreign","exs":[{"use":"外 + N: bên ngoài.","ex":"门外有人找你。","py":"Mén wài yǒu rén zhǎo nǐ.","vi":"Ngoài cửa có người tìm bạn.","en":"Someone is looking for you outside the door."},{"use":"国外: nước ngoài.","ex":"他去国外学习了。","py":"Tā qù guówài xuéxí le.","vi":"Anh ấy ra nước ngoài học.","en":"He went abroad to study."},{"use":"城外: ngoại thành.","ex":"我家在城外。","py":"Wǒ jiā zài chéng wài.","vi":"Nhà tôi ở ngoài thành phố.","en":"My home is outside the city."}]},"羊肉":{"en":"mutton; lamb","exs":[{"use":"吃 + 羊肉.","ex":"北方人爱吃羊肉。","py":"Běifāng rén ài chī yángròu.","vi":"Người miền bắc thích ăn thịt cừu.","en":"Northerners love eating lamb."},{"use":"羊肉 + 汤/串.","ex":"冬天喝一碗羊肉汤很舒服。","py":"Dōngtiān hē yì wǎn yángròu tāng hěn shūfu.","vi":"Mùa đông uống một bát canh thịt dê rất dễ chịu.","en":"A bowl of lamb soup is comforting in winter."},{"use":"买 + 公斤.","ex":"请给我两公斤羊肉。","py":"Qǐng gěi wǒ liǎng gōngjīn yángròu.","vi":"Cho tôi hai ký thịt cừu.","en":"Two kilos of lamb, please."}]},"因为":{"en":"because","exs":[{"use":"因为 + nguyên nhân，所以 + kết quả.","ex":"因为太忙，我没吃饭。","py":"Yīnwèi tài máng, wǒ méi chī fàn.","vi":"Vì bận quá nên tôi chưa ăn cơm.","en":"I was too busy to eat."},{"use":"Trả lời câu hỏi 为什么.","ex":"你为什么哭？因为我很难过。","py":"Nǐ wèi shénme kū? Yīnwèi wǒ hěn nánguò.","vi":"Sao bạn khóc? Vì tôi buồn.","en":"Why are you crying? Because I'm sad."},{"use":"Có thể đặt sau vế kết quả.","ex":"我没去，因为我生病了。","py":"Wǒ méi qù, yīnwèi wǒ shēng bìng le.","vi":"Tôi không đi, vì tôi bị ốm.","en":"I didn't go because I was sick."}]},"游泳":{"en":"to swim","exs":[{"use":"游泳 là động từ li hợp (游 + 泳).","ex":"我夏天常去游泳。","py":"Wǒ xiàtiān cháng qù yóu yǒng.","vi":"Mùa hè tôi hay đi bơi.","en":"I often go swimming in summer."},{"use":"会/喜欢 + 游泳.","ex":"他游泳游得很快。","py":"Tā yóu yǒng yóu de hěn kuài.","vi":"Anh ấy bơi rất nhanh.","en":"He swims very fast."},{"use":"游泳 + 池.","ex":"学校旁边有一个游泳池。","py":"Xuéxiào pángbiān yǒu yí ge yóuyǒngchí.","vi":"Cạnh trường có một bể bơi.","en":"There's a swimming pool next to the school."}]},"好吃":{"en":"delicious","exs":[{"use":"好吃 chỉ đồ ăn ngon.","ex":"这个菜真好吃。","py":"Zhège cài zhēn hǎochī.","vi":"Món này ngon thật.","en":"This dish is really delicious."},{"use":"很好吃/不好吃.","ex":"面条不太好吃。","py":"Miàntiáo bú tài hǎochī.","vi":"Mì không ngon lắm.","en":"The noodles aren't very tasty."},{"use":"好吃 + 的 + N.","ex":"我知道一家好吃的饭馆。","py":"Wǒ zhīdào yì jiā hǎochī de fànguǎn.","vi":"Tôi biết một quán ăn ngon.","en":"I know a delicious restaurant."}]},"公斤":{"en":"kilogram","exs":[{"use":"Số + 公斤.","ex":"我买了两公斤苹果。","py":"Wǒ mǎi le liǎng gōngjīn píngguǒ.","vi":"Tôi mua hai ký táo.","en":"I bought two kilos of apples."},{"use":"Hỏi cân nặng: 多少公斤？","ex":"你多少公斤？","py":"Nǐ duōshao gōngjīn?","vi":"Bạn nặng bao nhiêu ký?","en":"How many kilos do you weigh?"},{"use":"公斤 ≈ 2 斤.","ex":"一公斤是两斤。","py":"Yì gōngjīn shì liǎng jīn.","vi":"Một ký là hai cân (cân Trung Quốc).","en":"One kilogram is two jin."}]},"经常":{"en":"often; frequently","exs":[{"use":"经常 + V: làm thường xuyên.","ex":"我经常去游泳。","py":"Wǒ jīngcháng qù yóu yǒng.","vi":"Tôi thường xuyên đi bơi.","en":"I often go swimming."},{"use":"Đứng trước động từ.","ex":"他经常迟到。","py":"Tā jīngcháng chídào.","vi":"Anh ấy hay đến muộn.","en":"He is often late."},{"use":"Phủ định: 不经常.","ex":"我不经常喝咖啡。","py":"Wǒ bù jīngcháng hē kāfēi.","vi":"Tôi không thường uống cà phê.","en":"I don't often drink coffee."}]},"自行车":{"en":"bicycle","exs":[{"use":"Lượng từ: 一辆自行车.","ex":"我骑自行车去上班。","py":"Wǒ qí zìxíngchē qù shàng bān.","vi":"Tôi đạp xe đi làm.","en":"I cycle to work."},{"use":"骑 + 自行车.","ex":"他买了一辆新自行车。","py":"Tā mǎi le yí liàng xīn zìxíngchē.","vi":"Anh ấy mua một chiếc xe đạp mới.","en":"He bought a new bicycle."},{"use":"自行车 + 很 + 方便.","ex":"在这儿骑自行车很方便。","py":"Zài zhèr qí zìxíngchē hěn fāngbiàn.","vi":"Ở đây đi xe đạp rất tiện.","en":"Biking here is very convenient."}]},"到":{"en":"to arrive; to reach","exs":[{"use":"到 + nơi: đến đâu.","ex":"我八点到公司。","py":"Wǒ bā diǎn dào gōngsī.","vi":"Tám giờ tôi đến công ty.","en":"I arrive at the company at eight."},{"use":"V + 到: bổ ngữ kết quả.","ex":"我找到了我的手机。","py":"Wǒ zhǎodào le wǒ de shǒujī.","vi":"Tôi đã tìm thấy điện thoại.","en":"I found my phone."},{"use":"从……到……: từ … đến ….","ex":"从家到学校要二十分钟。","py":"Cóng jiā dào xuéxiào yào èrshí fēnzhōng.","vi":"Từ nhà đến trường mất hai mươi phút.","en":"It takes twenty minutes from home to school."}]},"公共汽车":{"en":"bus","exs":[{"use":"坐 + 公共汽车: đi xe buýt.","ex":"我坐公共汽车去上班。","py":"Wǒ zuò gōnggòng qìchē qù shàng bān.","vi":"Tôi đi xe buýt đi làm.","en":"I take the bus to work."},{"use":"Lượng từ 辆.","ex":"一辆公共汽车来了。","py":"Yí liàng gōnggòng qìchē lái le.","vi":"Một chiếc xe buýt đã đến.","en":"A bus has arrived."},{"use":"Rút gọn: 公交车.","ex":"公共汽车站在前面。","py":"Gōnggòng qìchē zhàn zài qiánmiàn.","vi":"Trạm xe buýt ở phía trước.","en":"The bus stop is up ahead."}]},"公司":{"en":"company","exs":[{"use":"在 + 公司 + 工作.","ex":"他在一家大公司工作。","py":"Tā zài yì jiā dà gōngsī gōngzuò.","vi":"Anh ấy làm ở một công ty lớn.","en":"He works at a big company."},{"use":"去/到 + 公司.","ex":"你几点到公司？","py":"Nǐ jǐ diǎn dào gōngsī?","vi":"Mấy giờ bạn đến công ty?","en":"What time do you get to the office?"},{"use":"离公司.","ex":"我家离公司很近。","py":"Wǒ jiā lí gōngsī hěn jìn.","vi":"Nhà tôi rất gần công ty.","en":"My home is close to the company."}]},"机场":{"en":"airport","exs":[{"use":"去机场: ra sân bay.","ex":"我们坐出租车去机场。","py":"Wǒmen zuò chūzūchē qù jīchǎng.","vi":"Chúng tôi đi taxi ra sân bay.","en":"We take a taxi to the airport."},{"use":"机场 + 离 + 市里 + 远.","ex":"机场离市里很远。","py":"Jīchǎng lí shìlǐ hěn yuǎn.","vi":"Sân bay cách trung tâm rất xa.","en":"The airport is far from downtown."},{"use":"在机场 + 接 + 人.","ex":"我在机场等你。","py":"Wǒ zài jīchǎng děng nǐ.","vi":"Tôi đợi bạn ở sân bay.","en":"I'll wait for you at the airport."}]},"教室":{"en":"classroom","exs":[{"use":"在 + 教室.","ex":"同学们都在教室里。","py":"Tóngxuémen dōu zài jiàoshì li.","vi":"Các bạn học đều ở trong phòng học.","en":"The classmates are all in the classroom."},{"use":"进/出 + 教室.","ex":"老师走进了教室。","py":"Lǎoshī zǒu jìn le jiàoshì.","vi":"Thầy giáo bước vào lớp.","en":"The teacher walked into the classroom."},{"use":"教室 + 里 + 有.","ex":"教室里有二十张桌子。","py":"Jiàoshì li yǒu èrshí zhāng zhuōzi.","vi":"Trong lớp có hai mươi cái bàn.","en":"There are twenty desks in the classroom."}]},"快":{"en":"fast; quick","exs":[{"use":"快 làm vị ngữ: nhanh.","ex":"他跑得很快。","py":"Tā pǎo de hěn kuài.","vi":"Anh ấy chạy rất nhanh.","en":"He runs very fast."},{"use":"快 + V: mau làm.","ex":"快走吧，要迟到了。","py":"Kuài zǒu ba, yào chídào le.","vi":"Đi mau lên, sắp muộn rồi.","en":"Hurry up, we'll be late."},{"use":"快……了: sắp ….","ex":"火车快到了。","py":"Huǒchē kuài dào le.","vi":"Tàu sắp đến rồi.","en":"The train is about to arrive."}]},"离":{"en":"to be away from","exs":[{"use":"A + 离 + B + 远/近: A cách B xa/gần.","ex":"我家离学校不远。","py":"Wǒ jiā lí xuéxiào bù yuǎn.","vi":"Nhà tôi cách trường không xa.","en":"My home isn't far from school."},{"use":"离 + 地点 + 多远？","ex":"这儿离机场有多远？","py":"Zhèr lí jīchǎng yǒu duō yuǎn?","vi":"Chỗ này cách sân bay bao xa?","en":"How far is the airport from here?"},{"use":"离 cũng dùng cho thời gian.","ex":"离考试还有三天。","py":"Lí kǎoshì hái yǒu sān tiān.","vi":"Còn ba ngày nữa là thi.","en":"There are three days until the exam."}]},"路":{"en":"road; way","exs":[{"use":"走路: đi bộ.","ex":"我走路去上班。","py":"Wǒ zǒu lù qù shàng bān.","vi":"Tôi đi bộ đi làm.","en":"I walk to work."},{"use":"问路: hỏi đường.","ex":"请问，去火车站怎么走？我迷路了。","py":"Qǐngwèn, qù huǒchēzhàn zěnme zǒu? Wǒ mí lù le.","vi":"Xin hỏi đi ga tàu thế nào? Tôi lạc đường rồi.","en":"Excuse me, how do I get to the station? I'm lost."},{"use":"路上: trên đường.","ex":"路上请注意安全。","py":"Lùshang qǐng zhùyì ānquán.","vi":"Trên đường nhớ chú ý an toàn.","en":"Be safe on the road."}]},"慢":{"en":"slow","exs":[{"use":"慢 làm vị ngữ.","ex":"这个车太慢了。","py":"Zhège chē tài màn le.","vi":"Chiếc xe này chậm quá.","en":"This bus is too slow."},{"use":"慢 + 点儿: chậm một chút.","ex":"请说慢一点儿。","py":"Qǐng shuō màn yìdiǎnr.","vi":"Xin nói chậm một chút.","en":"Please speak more slowly."},{"use":"慢走: đi cẩn thận (lời tiễn).","ex":"您慢走，再见！","py":"Nín màn zǒu, zàijiàn!","vi":"Bạn đi cẩn thận nhé, tạm biệt!","en":"Take care, goodbye!"}]},"小时":{"en":"hour","exs":[{"use":"Số + 个 + 小时: khoảng thời gian.","ex":"我睡了八个小时。","py":"Wǒ shuì le bā ge xiǎoshí.","vi":"Tôi đã ngủ tám tiếng.","en":"I slept for eight hours."},{"use":"一个小时 / 半个小时.","ex":"到机场要一个半小时。","py":"Dào jīchǎng yào yí ge bàn xiǎoshí.","vi":"Đến sân bay mất một tiếng rưỡi.","en":"It takes an hour and a half to get to the airport."},{"use":"小时 chỉ độ dài, 点 chỉ thời điểm.","ex":"他每天工作九个小时。","py":"Tā měi tiān gōngzuò jiǔ ge xiǎoshí.","vi":"Mỗi ngày anh ấy làm việc chín tiếng.","en":"He works nine hours a day."}]},"远":{"en":"far; distant","exs":[{"use":"很远 / 不远.","ex":"学校离这儿很远。","py":"Xuéxiào lí zhèr hěn yuǎn.","vi":"Trường cách đây rất xa.","en":"The school is far from here."},{"use":"远不远？: có xa không?","ex":"你家离公司远不远？","py":"Nǐ jiā lí gōngsī yuǎn bu yuǎn?","vi":"Nhà bạn có xa công ty không?","en":"Is your home far from the company?"},{"use":"Trái nghĩa 近.","ex":"不太远，走路十分钟就到。","py":"Bú tài yuǎn, zǒu lù shí fēnzhōng jiù dào.","vi":"Không xa lắm, đi bộ mười phút là tới.","en":"Not too far, ten minutes' walk."}]},"走":{"en":"to walk; to leave","exs":[{"use":"走 + 路/去: đi bộ.","ex":"我们走着去吧。","py":"Wǒmen zǒuzhe qù ba.","vi":"Chúng ta đi bộ đến đó nhé.","en":"Let's walk there."},{"use":"走了: rời đi rồi.","ex":"他已经走了。","py":"Tā yǐjīng zǒu le.","vi":"Anh ấy đã đi rồi.","en":"He has already left."},{"use":"往 + hướng + 走.","ex":"往前走，就是银行。","py":"Wǎng qián zǒu, jiù shì yínháng.","vi":"Đi thẳng về phía trước là ngân hàng.","en":"Go straight ahead and you'll see the bank."}]},"过":{"en":"to pass; to spend (time)","exs":[{"use":"过 + 时间/节日: trải qua.","ex":"我们怎么过周末？","py":"Wǒmen zěnme guò zhōumò?","vi":"Chúng ta trải qua cuối tuần thế nào?","en":"How shall we spend the weekend?"},{"use":"过 + 地点: đi qua.","ex":"过了这个路口就是公司。","py":"Guò le zhège lùkǒu jiù shì gōngsī.","vi":"Qua ngã tư này là công ty.","en":"The company is right past this intersection."},{"use":"过生日/过年.","ex":"明天我过生日。","py":"Míngtiān wǒ guò shēngrì.","vi":"Ngày mai tôi mừng sinh nhật.","en":"Tomorrow is my birthday."}]},"白":{"en":"white","exs":[{"use":"白 + N: màu trắng.","ex":"她穿着白衬衫。","py":"Tā chuānzhe bái chènshān.","vi":"Cô ấy mặc áo sơ mi trắng.","en":"She is wearing a white shirt."},{"use":"白 làm vị ngữ.","ex":"这朵花很白。","py":"Zhè duǒ huā hěn bái.","vi":"Bông hoa này rất trắng.","en":"This flower is very white."},{"use":"白色 + 的 + N.","ex":"我要白色的，不要黑色的。","py":"Wǒ yào báisè de, bú yào hēisè de.","vi":"Tôi muốn cái trắng, không lấy cái đen.","en":"I want the white one, not the black one."}]},"等":{"en":"to wait","exs":[{"use":"等 + người: đợi ai.","ex":"请你等我一下。","py":"Qǐng nǐ děng wǒ yíxià.","vi":"Bạn đợi tôi một chút nhé.","en":"Please wait for me a moment."},{"use":"等 + 一会儿.","ex":"我们等了半个小时。","py":"Wǒmen děng le bàn ge xiǎoshí.","vi":"Chúng tôi đã đợi nửa tiếng.","en":"We waited for half an hour."},{"use":"等……再……: đợi … rồi ….","ex":"等我想想再告诉你。","py":"Děng wǒ xiǎng xiǎng zài gàosu nǐ.","vi":"Để tôi nghĩ rồi báo bạn sau.","en":"Let me think it over and tell you later."}]},"服务员":{"en":"waiter/waitress; attendant","exs":[{"use":"Gọi nhân viên: 服务员！","ex":"服务员，请给我菜单。","py":"Fúwùyuán, qǐng gěi wǒ càidān.","vi":"Phục vụ ơi, cho tôi xem thực đơn.","en":"Waiter, may I have the menu?"},{"use":"当/做 + 服务员.","ex":"她在饭馆当服务员。","py":"Tā zài fànguǎn dāng fúwùyuán.","vi":"Cô ấy làm phục vụ ở nhà hàng.","en":"She works as a waitress at a restaurant."},{"use":"服务员 + 很 + 热情.","ex":"这里的服务员很热情。","py":"Zhèlǐ de fúwùyuán hěn rèqíng.","vi":"Nhân viên ở đây rất nhiệt tình.","en":"The staff here are very friendly."}]},"告诉":{"en":"to tell","exs":[{"use":"告诉 + người + nội dung.","ex":"请告诉我你的电话号码。","py":"Qǐng gàosu wǒ nǐ de diànhuà hàomǎ.","vi":"Xin cho tôi biết số điện thoại của bạn.","en":"Please tell me your phone number."},{"use":"告诉 + 人 + 一件事.","ex":"他告诉我明天不上课。","py":"Tā gàosu wǒ míngtiān bú shàng kè.","vi":"Anh ấy nói với tôi ngày mai không có tiết.","en":"He told me there is no class tomorrow."},{"use":"别告诉……: đừng nói với ….","ex":"别告诉他这件事。","py":"Bié gàosu tā zhè jiàn shì.","vi":"Đừng nói chuyện này cho anh ấy.","en":"Don't tell him about this."}]},"贵":{"en":"expensive","exs":[{"use":"太贵了: đắt quá.","ex":"这个太贵了。","py":"Zhège tài guì le.","vi":"Cái này đắt quá.","en":"This is too expensive."},{"use":"不贵: không đắt.","ex":"这里的东西不贵。","py":"Zhèlǐ de dōngxi bú guì.","vi":"Đồ ở đây không đắt.","en":"Things here aren't expensive."},{"use":"您贵姓？: ông họ gì ạ (lịch sự).","ex":"请问您贵姓？","py":"Qǐngwèn nín guì xìng?","vi":"Xin hỏi quý danh của ông là gì?","en":"May I ask your surname?"}]},"黑":{"en":"black","exs":[{"use":"黑 + N.","ex":"他有一只黑猫。","py":"Tā yǒu yì zhī hēi māo.","vi":"Anh ấy có một con mèo đen.","en":"He has a black cat."},{"use":"天黑了: trời tối rồi.","ex":"天黑了，我们回家吧。","py":"Tiān hēi le, wǒmen huí jiā ba.","vi":"Trời tối rồi, chúng ta về nhà thôi.","en":"It's dark; let's go home."},{"use":"黑色 + 的.","ex":"我喜欢黑色的包。","py":"Wǒ xǐhuan hēisè de bāo.","vi":"Tôi thích túi màu đen.","en":"I like black bags."}]},"让":{"en":"to let; to allow; to make","exs":[{"use":"让 + 人 + V: để/cho ai làm gì.","ex":"妈妈让我早点儿睡觉。","py":"Māma ràng wǒ zǎodiǎnr shuì jiào.","vi":"Mẹ bảo tôi đi ngủ sớm.","en":"Mom told me to go to bed early."},{"use":"让 + 我 + V: để tôi.","ex":"让我想想再告诉你。","py":"Ràng wǒ xiǎng xiǎng zài gàosu nǐ.","vi":"Để tôi nghĩ rồi nói bạn sau.","en":"Let me think and I'll tell you."},{"use":"Phủ định: 不让.","ex":"老师不让我们用手机。","py":"Lǎoshī bú ràng wǒmen yòng shǒujī.","vi":"Thầy không cho chúng tôi dùng điện thoại.","en":"The teacher doesn't let us use phones."}]},"事情":{"en":"thing; matter; affair","exs":[{"use":"有事情: có việc.","ex":"我有一件事情想问你。","py":"Wǒ yǒu yí jiàn shìqing xiǎng wèn nǐ.","vi":"Tôi có một việc muốn hỏi bạn.","en":"I have something I want to ask you."},{"use":"做事情.","ex":"他今天有很多事情要做。","py":"Tā jīntiān yǒu hěn duō shìqing yào zuò.","vi":"Hôm nay anh ấy có nhiều việc phải làm.","en":"He has many things to do today."},{"use":"什么事情？","ex":"发生了什么事情？","py":"Fāshēng le shénme shìqing?","vi":"Đã xảy ra chuyện gì?","en":"What happened?"}]},"再":{"en":"again; then","exs":[{"use":"再 + V: lặp lại trong tương lai.","ex":"请你再说一遍。","py":"Qǐng nǐ zài shuō yí biàn.","vi":"Xin bạn nói lại một lần nữa.","en":"Please say it once more."},{"use":"先……再……: trước … rồi ….","ex":"先吃饭，再看电影。","py":"Xiān chī fàn, zài kàn diànyǐng.","vi":"Ăn cơm trước, rồi xem phim.","en":"Eat first, then watch the movie."},{"use":"再见: tạm biệt.","ex":"明天再见！","py":"Míngtiān zàijiàn!","vi":"Mai gặp lại nhé!","en":"See you tomorrow!"}]},"找":{"en":"to look for","exs":[{"use":"找 + vật: tìm đồ.","ex":"我在找我的手机。","py":"Wǒ zài zhǎo wǒ de shǒujī.","vi":"Tôi đang tìm điện thoại.","en":"I'm looking for my phone."},{"use":"找 + 人: tìm gặp ai.","ex":"老师找你有事。","py":"Lǎoshī zhǎo nǐ yǒu shì.","vi":"Thầy tìm bạn có việc.","en":"The teacher wants to see you."},{"use":"找到/找不到.","ex":"我找了半天也没找到。","py":"Wǒ zhǎo le bàntiān yě méi zhǎodào.","vi":"Tôi tìm mãi mà không thấy.","en":"I searched for ages but couldn't find it."}]},"从":{"en":"from","exs":[{"use":"从 + nơi/thời gian + V.","ex":"他从北京来。","py":"Tā cóng Běijīng lái.","vi":"Anh ấy đến từ Bắc Kinh.","en":"He comes from Beijing."},{"use":"从……到…….","ex":"我从早上八点工作到晚上六点。","py":"Wǒ cóng zǎoshang bā diǎn gōngzuò dào wǎnshang liù diǎn.","vi":"Tôi làm việc từ tám giờ sáng đến sáu giờ tối.","en":"I work from 8 a.m. to 6 p.m."},{"use":"从 + 现在 + 开始.","ex":"从现在开始，我们说汉语。","py":"Cóng xiànzài kāishǐ, wǒmen shuō Hànyǔ.","vi":"Từ bây giờ chúng ta nói tiếng Hán.","en":"From now on, let's speak Chinese."}]},"错":{"en":"wrong; incorrect","exs":[{"use":"错了: sai rồi.","ex":"这个字写错了。","py":"Zhège zì xiě cuò le.","vi":"Chữ này viết sai rồi.","en":"This character is written wrong."},{"use":"V + 错: bổ ngữ kết quả.","ex":"对不起，我走错了。","py":"Duìbuqǐ, wǒ zǒu cuò le.","vi":"Xin lỗi, tôi đi nhầm rồi.","en":"Sorry, I went the wrong way."},{"use":"没错: đúng vậy.","ex":"你说得没错。","py":"Nǐ shuō de méi cuò.","vi":"Bạn nói không sai.","en":"You're right."}]},"第一":{"en":"first","exs":[{"use":"第 + số: số thứ tự.","ex":"他考了第一名。","py":"Tā kǎo le dì yī míng.","vi":"Anh ấy thi đứng nhất.","en":"He ranked first in the exam."},{"use":"第一次: lần đầu.","ex":"这是我第一次来中国。","py":"Zhè shì wǒ dì yī cì lái Zhōngguó.","vi":"Đây là lần đầu tôi đến Trung Quốc.","en":"This is my first time in China."},{"use":"第一 + N.","ex":"第一课很简单。","py":"Dì yī kè hěn jiǎndān.","vi":"Bài một rất đơn giản.","en":"Lesson one is very simple."}]},"懂":{"en":"to understand","exs":[{"use":"懂 + N: hiểu cái gì.","ex":"我不懂这个词。","py":"Wǒ bù dǒng zhège cí.","vi":"Tôi không hiểu từ này.","en":"I don't understand this word."},{"use":"听懂/看懂: nghe/đọc hiểu.","ex":"你听懂了吗？","py":"Nǐ tīng dǒng le ma?","vi":"Bạn nghe hiểu chưa?","en":"Did you understand?"},{"use":"懂 + 汉语.","ex":"他懂一点儿汉语。","py":"Tā dǒng yìdiǎnr Hànyǔ.","vi":"Anh ấy biết chút tiếng Hán.","en":"He understands a bit of Chinese."}]},"上班":{"en":"to go to work","exs":[{"use":"上班 là động từ li hợp.","ex":"我八点上班。","py":"Wǒ bā diǎn shàng bān.","vi":"Tám giờ tôi đi làm.","en":"I start work at eight."},{"use":"去 + 上班: đi làm.","ex":"他骑自行车去上班。","py":"Tā qí zìxíngchē qù shàng bān.","vi":"Anh ấy đạp xe đi làm.","en":"He bikes to work."},{"use":"Trái nghĩa 下班.","ex":"你几点下班？","py":"Nǐ jǐ diǎn xià bān?","vi":"Mấy giờ bạn tan làm?","en":"What time do you get off work?"}]},"题":{"en":"question; problem (in exam)","exs":[{"use":"Lượng từ: 一道题.","ex":"这道题很难。","py":"Zhè dào tí hěn nán.","vi":"Câu này rất khó.","en":"This question is hard."},{"use":"做题: làm bài.","ex":"我今天做了二十道题。","py":"Wǒ jīntiān zuò le èrshí dào tí.","vi":"Hôm nay tôi làm hai mươi câu.","en":"I did twenty questions today."},{"use":"题 + 太 + 多.","ex":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuò wán.","vi":"Nhiều câu quá, tôi làm chưa xong.","en":"There were too many questions; I didn't finish."}]},"跳舞":{"en":"to dance","exs":[{"use":"跳舞 là động từ li hợp.","ex":"她喜欢跳舞。","py":"Tā xǐhuan tiào wǔ.","vi":"Cô ấy thích nhảy.","en":"She likes dancing."},{"use":"跳 + 得 + 好: nhảy giỏi.","ex":"她跳舞跳得很好。","py":"Tā tiào wǔ tiào de hěn hǎo.","vi":"Cô ấy nhảy rất đẹp.","en":"She dances very well."},{"use":"去 + 跳舞.","ex":"周末我们去跳舞吧。","py":"Zhōumò wǒmen qù tiào wǔ ba.","vi":"Cuối tuần chúng ta đi nhảy nhé.","en":"Let's go dancing this weekend."}]},"完":{"en":"to finish; to end","exs":[{"use":"V + 完: làm xong.","ex":"我做完作业了。","py":"Wǒ zuò wán zuòyè le.","vi":"Tôi làm xong bài tập rồi.","en":"I finished my homework."},{"use":"没 + V + 完: chưa xong.","ex":"这本书我还没看完。","py":"Zhè běn shū wǒ hái méi kàn wán.","vi":"Quyển sách này tôi chưa đọc xong.","en":"I haven't finished this book."},{"use":"吃完饭以后.","ex":"吃完饭，我们去散步。","py":"Chī wán fàn, wǒmen qù sàn bù.","vi":"Ăn xong, chúng ta đi dạo.","en":"After eating, we go for a walk."}]},"问题":{"en":"question; problem","exs":[{"use":"问 + 问题: đặt câu hỏi.","ex":"我有一个问题想问老师。","py":"Wǒ yǒu yí ge wèntí xiǎng wèn lǎoshī.","vi":"Tôi có một câu hỏi muốn hỏi thầy.","en":"I have a question for the teacher."},{"use":"没问题: không vấn đề gì.","ex":"这件事没问题。","py":"Zhè jiàn shì méi wèntí.","vi":"Việc này không có vấn đề gì.","en":"No problem with this."},{"use":"有问题: có trục trặc.","ex":"我的电脑有问题。","py":"Wǒ de diànnǎo yǒu wèntí.","vi":"Máy tính của tôi có vấn đề.","en":"There's a problem with my computer."}]},"希望":{"en":"to hope; to wish","exs":[{"use":"希望 + câu: mong rằng.","ex":"我希望你快点儿好起来。","py":"Wǒ xīwàng nǐ kuài diǎnr hǎo qǐlai.","vi":"Tôi mong bạn mau khỏe lại.","en":"I hope you get better soon."},{"use":"希望 + V.","ex":"他希望明年去中国学习。","py":"Tā xīwàng míngnián qù Zhōngguó xuéxí.","vi":"Anh ấy hy vọng sang năm đi Trung Quốc học.","en":"He hopes to study in China next year."},{"use":"Danh từ: 有希望.","ex":"这次考试你有希望得第一。","py":"Zhè cì kǎoshì nǐ yǒu xīwàng dé dì yī.","vi":"Kỳ thi này bạn có hy vọng đạt hạng nhất.","en":"You have a chance of coming first."}]},"欢迎":{"en":"to welcome","exs":[{"use":"欢迎 + 人: chào đón ai.","ex":"欢迎你来我家。","py":"Huānyíng nǐ lái wǒ jiā.","vi":"Chào mừng bạn đến nhà tôi.","en":"Welcome to my home."},{"use":"欢迎光临: kính chào quý khách.","ex":"欢迎光临，请进！","py":"Huānyíng guānglín, qǐng jìn!","vi":"Kính chào quý khách, mời vào!","en":"Welcome, please come in!"},{"use":"受欢迎: được yêu thích.","ex":"这首歌很受欢迎。","py":"Zhè shǒu gē hěn shòu huānyíng.","vi":"Bài hát này rất được ưa chuộng.","en":"This song is very popular."}]},"帮助":{"en":"to help; to assist","exs":[{"use":"帮助 + 人: giúp ai.","ex":"谢谢你帮助我。","py":"Xièxie nǐ bāngzhù wǒ.","vi":"Cảm ơn bạn đã giúp đỡ tôi.","en":"Thank you for helping me."},{"use":"帮助 + 人 + V.","ex":"老师帮助我们学习汉语。","py":"Lǎoshī bāngzhù wǒmen xuéxí Hànyǔ.","vi":"Thầy giúp chúng tôi học tiếng Hán.","en":"The teacher helps us learn Chinese."},{"use":"Danh từ: 有帮助.","ex":"这本书对你很有帮助。","py":"Zhè běn shū duì nǐ hěn yǒu bāngzhù.","vi":"Quyển sách này rất có ích cho bạn.","en":"This book is very helpful to you."}]},"别":{"en":"don't","exs":[{"use":"别 + V: đừng làm gì.","ex":"别走，再坐一会儿。","py":"Bié zǒu, zài zuò yíhuìr.","vi":"Đừng đi, ngồi thêm chút nữa.","en":"Don't go, stay a little longer."},{"use":"别……了: đừng … nữa.","ex":"别找了，手机在桌子上呢。","py":"Bié zhǎo le, shǒujī zài zhuōzi shang ne.","vi":"Đừng tìm nữa, điện thoại ở trên bàn kìa.","en":"Stop looking; the phone is on the desk."},{"use":"别 + 忘 + 了.","ex":"别忘了带钥匙。","py":"Bié wàng le dài yàoshi.","vi":"Đừng quên mang chìa khóa.","en":"Don't forget your keys."}]},"哥哥":{"en":"elder brother","exs":[{"use":"Gọi anh ruột.","ex":"我哥哥是老师。","py":"Wǒ gēge shì lǎoshī.","vi":"Anh trai tôi là giáo viên.","en":"My older brother is a teacher."},{"use":"哥哥 + 比 + 我 + 大.","ex":"哥哥比我大三岁。","py":"Gēge bǐ wǒ dà sān suì.","vi":"Anh hơn tôi ba tuổi.","en":"My brother is three years older than me."},{"use":"哥哥 + 和 + 弟弟.","ex":"哥哥和弟弟都爱踢足球。","py":"Gēge hé dìdi dōu ài tī zúqiú.","vi":"Anh và em đều thích đá bóng.","en":"The brothers both love football."}]},"鸡蛋":{"en":"(hen's) egg","exs":[{"use":"Lượng từ: 一个鸡蛋.","ex":"我早上吃两个鸡蛋。","py":"Wǒ zǎoshang chī liǎng ge jīdàn.","vi":"Sáng tôi ăn hai quả trứng.","en":"I eat two eggs in the morning."},{"use":"买鸡蛋.","ex":"请帮我买一公斤鸡蛋。","py":"Qǐng bāng wǒ mǎi yì gōngjīn jīdàn.","vi":"Nhờ bạn mua giúp tôi một ký trứng.","en":"Please buy me a kilo of eggs."},{"use":"鸡蛋 + 面/饭.","ex":"我喜欢吃西红柿鸡蛋面。","py":"Wǒ xǐhuan chī xīhóngshì jīdàn miàn.","vi":"Tôi thích ăn mì cà chua trứng.","en":"I like tomato and egg noodles."}]},"课":{"en":"class; lesson","exs":[{"use":"上课: vào học.","ex":"我们八点上课。","py":"Wǒmen bā diǎn shàng kè.","vi":"Tám giờ chúng tôi vào học.","en":"Our class starts at eight."},{"use":"第 + số + 课: bài thứ mấy.","ex":"今天我们学第十课。","py":"Jīntiān wǒmen xué dì shí kè.","vi":"Hôm nay chúng ta học bài mười.","en":"Today we study Lesson 10."},{"use":"下课: tan học.","ex":"下课以后你去哪儿？","py":"Xià kè yǐhòu nǐ qù nǎr?","vi":"Tan học rồi bạn đi đâu?","en":"Where are you going after class?"}]},"手机":{"en":"cell phone","exs":[{"use":"Lượng từ: 一部手机.","ex":"我的手机在桌子上。","py":"Wǒ de shǒujī zài zhuōzi shang.","vi":"Điện thoại của tôi ở trên bàn.","en":"My phone is on the desk."},{"use":"手机 + 号码.","ex":"你的手机号码是多少？","py":"Nǐ de shǒujī hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?","en":"What's your cell phone number?"},{"use":"用手机 + V.","ex":"我常用手机看新闻。","py":"Wǒ cháng yòng shǒujī kàn xīnwén.","vi":"Tôi hay đọc tin tức bằng điện thoại.","en":"I often read the news on my phone."}]},"西瓜":{"en":"watermelon","exs":[{"use":"Lượng từ: 一个/一块西瓜.","ex":"夏天我最爱吃西瓜。","py":"Xiàtiān wǒ zuì ài chī xīguā.","vi":"Mùa hè tôi thích ăn dưa hấu nhất.","en":"I love watermelon most in summer."},{"use":"买西瓜.","ex":"他买了一个大西瓜。","py":"Tā mǎi le yí ge dà xīguā.","vi":"Anh ấy mua một quả dưa hấu lớn.","en":"He bought a big watermelon."},{"use":"西瓜 + 很甜.","ex":"这个西瓜很甜。","py":"Zhège xīguā hěn tián.","vi":"Quả dưa hấu này rất ngọt.","en":"This watermelon is very sweet."}]},"洗":{"en":"to wash","exs":[{"use":"洗 + N: rửa/giặt.","ex":"我在洗衣服。","py":"Wǒ zài xǐ yīfu.","vi":"Tôi đang giặt quần áo.","en":"I'm washing clothes."},{"use":"洗手/洗脸/洗澡.","ex":"吃饭以前要洗手。","py":"Chī fàn yǐqián yào xǐ shǒu.","vi":"Trước khi ăn phải rửa tay.","en":"Wash your hands before eating."},{"use":"洗 + 好/干净.","ex":"衣服洗干净了。","py":"Yīfu xǐ gānjìng le.","vi":"Quần áo giặt sạch rồi.","en":"The clothes are washed clean."}]},"正在":{"en":"in the process of","exs":[{"use":"正在 + V (+ 呢): đang làm.","ex":"他正在看电视。","py":"Tā zhèngzài kàn diànshì.","vi":"Anh ấy đang xem tivi.","en":"He is watching TV."},{"use":"正在 + V + 呢.","ex":"我正在吃饭呢。","py":"Wǒ zhèngzài chī fàn ne.","vi":"Tôi đang ăn cơm đấy.","en":"I'm eating right now."},{"use":"Thường dùng với hành động đang diễn ra.","ex":"妈妈正在洗西瓜。","py":"Māma zhèngzài xǐ xīguā.","vi":"Mẹ đang rửa dưa hấu.","en":"Mom is washing the watermelon."}]},"比":{"en":"than; compared to","exs":[{"use":"A + 比 + B + adj: A hơn B.","ex":"他比我高。","py":"Tā bǐ wǒ gāo.","vi":"Anh ấy cao hơn tôi.","en":"He is taller than me."},{"use":"A + 比 + B + adj + số lượng.","ex":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","vi":"Anh ấy hơn tôi ba tuổi.","en":"He is three years older than me."},{"use":"Không dùng 很 trước adj; dùng 更/还 nếu cần.","ex":"今天比昨天更冷。","py":"Jīntiān bǐ zuótiān gèng lěng.","vi":"Hôm nay lạnh hơn hôm qua.","en":"Today is colder than yesterday."}]},"唱歌":{"en":"to sing","exs":[{"use":"唱歌 là động từ li hợp.","ex":"她喜欢唱歌。","py":"Tā xǐhuan chàng gē.","vi":"Cô ấy thích hát.","en":"She likes singing."},{"use":"唱 + 一首歌.","ex":"请你给我们唱一首歌。","py":"Qǐng nǐ gěi wǒmen chàng yì shǒu gē.","vi":"Mời bạn hát cho chúng tôi một bài.","en":"Please sing us a song."},{"use":"唱歌 + 唱得 + adj.","ex":"他唱歌唱得很好听。","py":"Tā chàng gē chàng de hěn hǎotīng.","vi":"Anh ấy hát rất hay.","en":"He sings beautifully."}]},"可能":{"en":"maybe; perhaps; probably","exs":[{"use":"可能 + V: có lẽ sẽ.","ex":"明天可能会下雨。","py":"Míngtiān kěnéng huì xià yǔ.","vi":"Ngày mai có thể sẽ mưa.","en":"It may rain tomorrow."},{"use":"可能 + 是 + ….","ex":"他可能是生病了。","py":"Tā kěnéng shì shēng bìng le.","vi":"Có lẽ anh ấy bị ốm.","en":"He may be sick."},{"use":"不可能: không thể nào.","ex":"这不可能是真的。","py":"Zhè bù kěnéng shì zhēn de.","vi":"Điều này không thể là thật.","en":"This can't be true."}]},"孩子":{"en":"child; kid","exs":[{"use":"Lượng từ: 一个孩子.","ex":"这个孩子很聪明。","py":"Zhège háizi hěn cōngming.","vi":"Đứa trẻ này rất thông minh.","en":"This child is very smart."},{"use":"我的孩子: con tôi.","ex":"他们有两个孩子。","py":"Tāmen yǒu liǎng ge háizi.","vi":"Họ có hai đứa con.","en":"They have two children."},{"use":"男孩子/女孩子.","ex":"那个男孩子是我弟弟。","py":"Nàge nánháizi shì wǒ dìdi.","vi":"Cậu bé kia là em trai tôi.","en":"That boy is my younger brother."}]},"男":{"en":"male; man","exs":[{"use":"男 + N: nam.","ex":"他是男老师。","py":"Tā shì nán lǎoshī.","vi":"Anh ấy là thầy giáo nam.","en":"He is a male teacher."},{"use":"男人/男孩.","ex":"那个男孩在踢球。","py":"Nàge nánhái zài tī qiú.","vi":"Cậu bé kia đang đá bóng.","en":"That boy is kicking a ball."},{"use":"男 + 女 (đối lập).","ex":"这里有男厕所和女厕所。","py":"Zhèlǐ yǒu nán cèsuǒ hé nǚ cèsuǒ.","vi":"Ở đây có nhà vệ sinh nam và nữ.","en":"There are men's and women's restrooms."}]},"女":{"en":"female; woman","exs":[{"use":"女 + N: nữ.","ex":"她是女医生。","py":"Tā shì nǚ yīshēng.","vi":"Cô ấy là bác sĩ nữ.","en":"She is a female doctor."},{"use":"女儿: con gái.","ex":"他有一个女儿。","py":"Tā yǒu yí ge nǚ'ér.","vi":"Anh ấy có một cô con gái.","en":"He has a daughter."},{"use":"女朋友/女孩.","ex":"那个女孩是我同学。","py":"Nàge nǚhái shì wǒ tóngxué.","vi":"Cô bé kia là bạn học của tôi.","en":"That girl is my classmate."}]},"便宜":{"en":"cheap; inexpensive","exs":[{"use":"很便宜 / 不便宜.","ex":"这里的水果很便宜。","py":"Zhèlǐ de shuǐguǒ hěn piányi.","vi":"Trái cây ở đây rất rẻ.","en":"Fruit here is very cheap."},{"use":"便宜 + 一点儿: rẻ chút.","ex":"能便宜一点儿吗？","py":"Néng piányi yìdiǎnr ma?","vi":"Bớt chút được không?","en":"Can you make it a bit cheaper?"},{"use":"比……便宜.","ex":"这件比那件便宜。","py":"Zhè jiàn bǐ nà jiàn piányi.","vi":"Cái này rẻ hơn cái kia.","en":"This one is cheaper than that one."}]},"去年":{"en":"last year","exs":[{"use":"去年 + V: năm ngoái làm gì.","ex":"我去年去过北京。","py":"Wǒ qùnián qù guo Běijīng.","vi":"Năm ngoái tôi đã đến Bắc Kinh.","en":"I went to Beijing last year."},{"use":"去年 + 夏天.","ex":"去年夏天特别热。","py":"Qùnián xiàtiān tèbié rè.","vi":"Mùa hè năm ngoái đặc biệt nóng.","en":"Last summer was especially hot."},{"use":"Đối lập 今年/明年.","ex":"他去年二十岁，今年二十一岁。","py":"Tā qùnián èrshí suì, jīnnián èrshíyī suì.","vi":"Năm ngoái anh ấy hai mươi, năm nay hai mốt.","en":"He was 20 last year and is 21 this year."}]},"说话":{"en":"to speak; to talk","exs":[{"use":"说话 là động từ li hợp.","ex":"请小声说话。","py":"Qǐng xiǎoshēng shuō huà.","vi":"Xin nói nhỏ thôi.","en":"Please speak quietly."},{"use":"跟 + 人 + 说话.","ex":"我想跟你说说话。","py":"Wǒ xiǎng gēn nǐ shuōshuo huà.","vi":"Tôi muốn nói chuyện với bạn.","en":"I'd like to talk with you."},{"use":"说话 + 的 + 声音.","ex":"他说话的声音很好听。","py":"Tā shuō huà de shēngyīn hěn hǎotīng.","vi":"Giọng nói của anh ấy rất hay.","en":"His speaking voice is pleasant."}]},"姓":{"en":"to be surnamed","exs":[{"use":"姓 + họ: họ là.","ex":"我姓王。","py":"Wǒ xìng Wáng.","vi":"Tôi họ Vương.","en":"My surname is Wang."},{"use":"您贵姓？: ông họ gì?","ex":"请问，你姓什么？","py":"Qǐngwèn, nǐ xìng shénme?","vi":"Xin hỏi bạn họ gì?","en":"May I ask your surname?"},{"use":"姓 + 名 + 叫 + ….","ex":"他姓李，叫李明。","py":"Tā xìng Lǐ, jiào Lǐ Míng.","vi":"Anh ấy họ Lý, tên là Lý Minh.","en":"His surname is Li; he is called Li Ming."}]},"右边":{"en":"right side","exs":[{"use":"N + 右边.","ex":"银行在书店右边。","py":"Yínháng zài shūdiàn yòubian.","vi":"Ngân hàng ở bên phải hiệu sách.","en":"The bank is to the right of the bookstore."},{"use":"右边 + 的 + N.","ex":"右边的椅子是我的。","py":"Yòubian de yǐzi shì wǒ de.","vi":"Chiếc ghế bên phải là của tôi.","en":"The chair on the right is mine."},{"use":"往右边走.","ex":"往右边走就是学校。","py":"Wǎng yòubian zǒu jiù shì xuéxiào.","vi":"Đi sang bên phải là trường.","en":"Go right and you'll see the school."}]},"穿":{"en":"to wear; to put on","exs":[{"use":"穿 + 衣服/鞋: mặc/đi.","ex":"她今天穿了一件红衣服。","py":"Tā jīntiān chuān le yí jiàn hóng yīfu.","vi":"Hôm nay cô ấy mặc áo đỏ.","en":"She is wearing a red top today."},{"use":"穿得 + 多/少.","ex":"外面很冷，多穿一点儿。","py":"Wàimian hěn lěng, duō chuān yìdiǎnr.","vi":"Bên ngoài lạnh, mặc thêm chút.","en":"It's cold outside; wear more."},{"use":"穿 + 着.","ex":"他穿着一双新鞋。","py":"Tā chuānzhe yì shuāng xīn xié.","vi":"Anh ấy đang đi một đôi giày mới.","en":"He is wearing a new pair of shoes."}]},"得":{"en":"particle introducing complement of degree","exs":[{"use":"V + 得 + adj: làm … như thế nào.","ex":"你穿得太少了。","py":"Nǐ chuān de tài shǎo le.","vi":"Bạn mặc ít quá.","en":"You're wearing too little."},{"use":"说得/跑得/吃得 + adj.","ex":"她说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","vi":"Cô ấy nói tiếng Hán rất giỏi.","en":"She speaks Chinese very well."},{"use":"Phủ định: 得 + 不 + adj.","ex":"他跑得不快。","py":"Tā pǎo de bú kuài.","vi":"Anh ấy chạy không nhanh.","en":"He doesn't run fast."}]},"弟弟":{"en":"younger brother","exs":[{"use":"Gọi em trai ruột.","ex":"我弟弟今年十岁。","py":"Wǒ dìdi jīnnián shí suì.","vi":"Em trai tôi năm nay mười tuổi.","en":"My younger brother is ten this year."},{"use":"弟弟 + 比 + 我 + 矮.","ex":"弟弟比我矮。","py":"Dìdi bǐ wǒ ǎi.","vi":"Em trai thấp hơn tôi.","en":"My brother is shorter than me."},{"use":"有 + 弟弟.","ex":"我有一个哥哥和一个弟弟。","py":"Wǒ yǒu yí ge gēge hé yí ge dìdi.","vi":"Tôi có một anh trai và một em trai.","en":"I have an older brother and a younger brother."}]},"进":{"en":"to enter; to come/go in","exs":[{"use":"进 + nơi: vào đâu.","ex":"请进！","py":"Qǐng jìn!","vi":"Mời vào!","en":"Please come in!"},{"use":"进来/进去 (bổ ngữ xu hướng).","ex":"外面冷，快进来吧。","py":"Wàimian lěng, kuài jìnlai ba.","vi":"Bên ngoài lạnh, mau vào đây.","en":"It's cold outside, come in."},{"use":"进 + 房间/教室.","ex":"他走进了房间。","py":"Tā zǒu jìn le fángjiān.","vi":"Anh ấy bước vào phòng.","en":"He walked into the room."}]},"近":{"en":"near; close","exs":[{"use":"很近 / 不近.","ex":"我家离公司很近。","py":"Wǒ jiā lí gōngsī hěn jìn.","vi":"Nhà tôi rất gần công ty.","en":"My home is very close to the company."},{"use":"离……近.","ex":"这儿离火车站不近。","py":"Zhèr lí huǒchēzhàn bú jìn.","vi":"Chỗ này không gần ga tàu.","en":"It's not close to the station from here."},{"use":"最近: dạo này.","ex":"最近你过得怎么样？","py":"Zuìjìn nǐ guò de zěnmeyàng?","vi":"Dạo này bạn sống thế nào?","en":"How have you been lately?"}]},"零":{"en":"zero","exs":[{"use":"零 trong số: 一百零一.","ex":"我的房间是二零三。","py":"Wǒ de fángjiān shì èr líng sān.","vi":"Phòng tôi là 203.","en":"My room is 203."},{"use":"零 + 度: 0 độ.","ex":"今天零下五度。","py":"Jīntiān líng xià wǔ dù.","vi":"Hôm nay âm năm độ.","en":"It's minus five degrees today."},{"use":"零 + 点: lúc 0 giờ.","ex":"现在是零点。","py":"Xiànzài shì líng diǎn.","vi":"Bây giờ là nửa đêm.","en":"It's midnight now."}]},"妻子":{"en":"wife","exs":[{"use":"我的妻子: vợ tôi.","ex":"他的妻子是老师。","py":"Tā de qīzi shì lǎoshī.","vi":"Vợ anh ấy là giáo viên.","en":"His wife is a teacher."},{"use":"妻子 + 和 + 丈夫.","ex":"妻子和丈夫都很忙。","py":"Qīzi hé zhàngfu dōu hěn máng.","vi":"Hai vợ chồng đều rất bận.","en":"The wife and husband are both busy."},{"use":"对 + 妻子 + 好.","ex":"他对妻子很好。","py":"Tā duì qīzi hěn hǎo.","vi":"Anh ấy đối xử với vợ rất tốt.","en":"He treats his wife very well."}]},"雪":{"en":"snow","exs":[{"use":"下雪: tuyết rơi.","ex":"北京冬天常下雪。","py":"Běijīng dōngtiān cháng xià xuě.","vi":"Mùa đông Bắc Kinh hay có tuyết.","en":"It often snows in Beijing in winter."},{"use":"雪 + 很 + 大.","ex":"今天的雪很大。","py":"Jīntiān de xuě hěn dà.","vi":"Hôm nay tuyết rơi rất dày.","en":"The snow is heavy today."},{"use":"看雪/玩雪.","ex":"孩子们在外面玩雪。","py":"Háizimen zài wàimian wán xuě.","vi":"Bọn trẻ đang chơi tuyết bên ngoài.","en":"The kids are playing in the snow."}]},"度":{"en":"degree","exs":[{"use":"Số + 度: nhiệt độ.","ex":"今天三十五度。","py":"Jīntiān sānshíwǔ dù.","vi":"Hôm nay ba mươi lăm độ.","en":"It's 35 degrees today."},{"use":"多少度？: bao nhiêu độ?","ex":"现在外面多少度？","py":"Xiànzài wàimian duōshao dù?","vi":"Bây giờ ngoài trời bao nhiêu độ?","en":"What's the temperature outside now?"},{"use":"零下 + 度.","ex":"冬天这儿常常零下十度。","py":"Dōngtiān zhèr chángcháng líng xià shí dù.","vi":"Mùa đông ở đây thường âm mười độ.","en":"Winters here often drop to minus ten."}]},"宾馆":{"en":"hotel","exs":[{"use":"住 + 宾馆: ở khách sạn.","ex":"我们住在这家宾馆。","py":"Wǒmen zhù zài zhè jiā bīnguǎn.","vi":"Chúng tôi ở khách sạn này.","en":"We are staying at this hotel."},{"use":"宾馆 + 在 + 地点.","ex":"宾馆就在火车站旁边。","py":"Bīnguǎn jiù zài huǒchēzhàn pángbiān.","vi":"Khách sạn ngay cạnh ga tàu.","en":"The hotel is right next to the train station."},{"use":"订宾馆.","ex":"我想订一个宾馆房间。","py":"Wǒ xiǎng dìng yí ge bīnguǎn fángjiān.","vi":"Tôi muốn đặt một phòng khách sạn.","en":"I'd like to book a hotel room."}]},"铅笔":{"en":"pencil","exs":[{"use":"Lượng từ: 一支铅笔.","ex":"我有一支铅笔。","py":"Wǒ yǒu yì zhī qiānbǐ.","vi":"Tôi có một cây bút chì.","en":"I have a pencil."},{"use":"用铅笔 + 写.","ex":"请用铅笔写名字。","py":"Qǐng yòng qiānbǐ xiě míngzi.","vi":"Xin viết tên bằng bút chì.","en":"Please write your name in pencil."},{"use":"铅笔 + 盒.","ex":"铅笔在铅笔盒里。","py":"Qiānbǐ zài qiānbǐhé li.","vi":"Bút chì ở trong hộp bút.","en":"The pencil is in the pencil case."}]},"往":{"en":"towards; to","exs":[{"use":"往 + hướng + V.","ex":"往前走五分钟就到。","py":"Wǎng qián zǒu wǔ fēnzhōng jiù dào.","vi":"Đi thẳng năm phút là tới.","en":"Walk straight for five minutes and you're there."},{"use":"往左/右 + 拐.","ex":"到路口往右拐。","py":"Dào lùkǒu wǎng yòu guǎi.","vi":"Đến ngã tư thì rẽ phải.","en":"Turn right at the intersection."},{"use":"往 + 地点 + 去.","ex":"这辆车往机场开。","py":"Zhè liàng chē wǎng jīchǎng kāi.","vi":"Chiếc xe này chạy về phía sân bay.","en":"This vehicle goes toward the airport."}]},"笑":{"en":"to smile; to laugh","exs":[{"use":"笑 + 着 + V: vừa cười vừa ….","ex":"她笑着说：“你好！”","py":"Tā xiàozhe shuō: \"Nǐ hǎo!\"","vi":"Cô ấy cười nói: \"Chào bạn!\"","en":"She said \"Hello!\" with a smile."},{"use":"笑 + 了.","ex":"大家都笑了。","py":"Dàjiā dōu xiào le.","vi":"Mọi người đều bật cười.","en":"Everybody laughed."},{"use":"别笑我.","ex":"我说错了，请别笑我。","py":"Wǒ shuō cuò le, qǐng bié xiào wǒ.","vi":"Tôi nói sai, xin đừng cười tôi.","en":"I said it wrong, please don't laugh at me."}]},"着":{"en":"particle marking a continuing state","exs":[{"use":"V + 着: trạng thái đang duy trì.","ex":"门开着呢。","py":"Mén kāizhe ne.","vi":"Cửa đang mở.","en":"The door is open."},{"use":"地点 + V + 着 + N: ở đâu có gì.","ex":"墙上挂着一张地图。","py":"Qiáng shang guàzhe yì zhāng dìtú.","vi":"Trên tường treo một tấm bản đồ.","en":"A map hangs on the wall."},{"use":"V + 着 + V: vừa … vừa ….","ex":"他笑着走进来。","py":"Tā xiàozhe zǒu jìnlai.","vi":"Anh ấy vừa cười vừa bước vào.","en":"He came in smiling."}]},"班":{"en":"class; grade; team","exs":[{"use":"我们班: lớp chúng tôi.","ex":"我们班有二十个学生。","py":"Wǒmen bān yǒu èrshí ge xuésheng.","vi":"Lớp chúng tôi có hai mươi học sinh.","en":"Our class has twenty students."},{"use":"上班/下班 cũng dùng 班.","ex":"他今天加班。","py":"Tā jīntiān jiābān.","vi":"Hôm nay anh ấy tăng ca.","en":"He works overtime today."},{"use":"班 + 老师.","ex":"我们班老师姓王。","py":"Wǒmen bān lǎoshī xìng Wáng.","vi":"Giáo viên lớp tôi họ Vương.","en":"Our class teacher is Mr. Wang."}]},"拿":{"en":"to hold; to take","exs":[{"use":"拿 + vật.","ex":"请把书拿来。","py":"Qǐng bǎ shū nálai.","vi":"Xin mang quyển sách lại đây.","en":"Please bring the book."},{"use":"手里拿着 + N.","ex":"他手里拿着一支铅笔。","py":"Tā shǒu li názhe yì zhī qiānbǐ.","vi":"Trong tay anh ấy cầm cây bút chì.","en":"He holds a pencil in his hand."},{"use":"拿出/拿走.","ex":"他从包里拿出手机。","py":"Tā cóng bāo li ná chū shǒujī.","vi":"Anh ấy lấy điện thoại ra khỏi túi.","en":"He took his phone out of the bag."}]},"一直":{"en":"straight; all along","exs":[{"use":"一直 + V: liên tục không ngừng.","ex":"他一直在等你。","py":"Tā yìzhí zài děng nǐ.","vi":"Anh ấy đợi bạn suốt.","en":"He has been waiting for you all along."},{"use":"一直 + 往 + 方向 + 走: đi thẳng.","ex":"一直往前走，就到宾馆了。","py":"Yìzhí wǎng qián zǒu, jiù dào bīnguǎn le.","vi":"Cứ đi thẳng là đến khách sạn.","en":"Go straight ahead to reach the hotel."},{"use":"一直 + 下雨.","ex":"昨天一直下雨。","py":"Zuótiān yìzhí xià yǔ.","vi":"Hôm qua mưa suốt.","en":"It rained all day yesterday."}]},"手":{"en":"hand","exs":[{"use":"洗手: rửa tay.","ex":"吃饭以前先洗手。","py":"Chī fàn yǐqián xiān xǐ shǒu.","vi":"Trước khi ăn hãy rửa tay.","en":"Wash your hands before eating."},{"use":"手 + 里: trong tay.","ex":"她手里拿着一本书。","py":"Tā shǒu li názhe yì běn shū.","vi":"Trong tay cô ấy cầm một quyển sách.","en":"She holds a book in her hand."},{"use":"手 + 机/表.","ex":"我的手很冷。","py":"Wǒ de shǒu hěn lěng.","vi":"Tay tôi rất lạnh.","en":"My hands are very cold."}]},"路口":{"en":"crossing; intersection","exs":[{"use":"路口 + 往 + hướng + 拐.","ex":"到了路口往左拐。","py":"Dào le lùkǒu wǎng zuǒ guǎi.","vi":"Đến ngã tư rẽ trái.","en":"At the intersection, turn left."},{"use":"在 + 路口 + 等.","ex":"我在路口等你。","py":"Wǒ zài lùkǒu děng nǐ.","vi":"Tôi đợi bạn ở ngã tư.","en":"I'll wait for you at the crossing."},{"use":"路口 + 站着 + 人.","ex":"路口站着一个人。","py":"Lùkǒu zhànzhe yí ge rén.","vi":"Ở ngã tư có một người đang đứng.","en":"A person is standing at the intersection."}]},"杨笑笑":{"en":"Yang Xiaoxiao (a person's name)","exs":[{"use":"Họ Dương, tên Tiếu Tiếu (chữ 笑 là \"cười\").","ex":"杨笑笑是我的同学。","py":"Yáng Xiàoxiao shì wǒ de tóngxué.","vi":"Dương Tiếu Tiếu là bạn học của tôi.","en":"Yang Xiaoxiao is my classmate."},{"use":"Gọi tên đầy đủ.","ex":"杨笑笑，你在哪儿？","py":"Yáng Xiàoxiao, nǐ zài nǎr?","vi":"Dương Tiếu Tiếu, bạn ở đâu?","en":"Yang Xiaoxiao, where are you?"},{"use":"Tên 笑笑 gợi hình ảnh hay cười.","ex":"笑笑总是笑着。","py":"Xiàoxiao zǒngshì xiàozhe.","vi":"Tiếu Tiếu lúc nào cũng cười.","en":"Xiaoxiao is always smiling."}]},"百":{"en":"hundred","exs":[{"use":"一百 = 100.","ex":"这本书一百块钱。","py":"Zhè běn shū yì bǎi kuài qián.","vi":"Quyển sách này một trăm tệ.","en":"This book costs a hundred yuan."},{"use":"数字: 两百 (không dùng 二百 thông thường).","ex":"他有两百个朋友。","py":"Tā yǒu liǎng bǎi ge péngyou.","vi":"Anh ấy có hai trăm người bạn.","en":"He has two hundred friends."},{"use":"百分之…: phần trăm.","ex":"百分之九十的人喜欢这个电影。","py":"Bǎi fēn zhī jiǔshí de rén xǐhuan zhège diànyǐng.","vi":"Chín mươi phần trăm người thích bộ phim này.","en":"Ninety percent of people like this movie."}]},"次":{"en":"time; occurrence","exs":[{"use":"V + 数 + 次: động lượng từ.","ex":"我去过两次北京。","py":"Wǒ qù guo liǎng cì Běijīng.","vi":"Tôi đã đến Bắc Kinh hai lần.","en":"I've been to Beijing twice."},{"use":"第一次: lần đầu.","ex":"这是我第一次吃羊肉。","py":"Zhè shì wǒ dì yī cì chī yángròu.","vi":"Đây là lần đầu tôi ăn thịt cừu.","en":"This is the first time I've eaten lamb."},{"use":"每次 / 这次.","ex":"这次考试很难。","py":"Zhè cì kǎoshì hěn nán.","vi":"Kỳ thi lần này rất khó.","en":"This exam was hard."}]},"但是":{"en":"but; yet","exs":[{"use":"虽然……，但是……: tuy … nhưng ….","ex":"他很忙，但是很快乐。","py":"Tā hěn máng, dànshì hěn kuàilè.","vi":"Anh ấy bận nhưng rất vui.","en":"He is busy but happy."},{"use":"但是 mở đầu vế đối lập.","ex":"我想去，但是没时间。","py":"Wǒ xiǎng qù, dànshì méi shíjiān.","vi":"Tôi muốn đi nhưng không có thời gian.","en":"I want to go, but I have no time."},{"use":"Thường đi với 可是.","ex":"天气很冷，但是他穿得很少。","py":"Tiānqì hěn lěng, dànshì tā chuān de hěn shǎo.","vi":"Trời lạnh mà anh ấy mặc rất ít.","en":"It's cold, but he's dressed lightly."}]},"晴":{"en":"sunny; clear","exs":[{"use":"晴天: trời nắng.","ex":"今天是晴天。","py":"Jīntiān shì qíngtiān.","vi":"Hôm nay trời nắng.","en":"Today is sunny."},{"use":"天 + 晴 + 了.","ex":"雨停了，天晴了。","py":"Yǔ tíng le, tiān qíng le.","vi":"Mưa tạnh, trời quang rồi.","en":"The rain stopped and it cleared up."},{"use":"Đối lập 阴.","ex":"昨天是阴天，今天是晴天。","py":"Zuótiān shì yīntiān, jīntiān shì qíngtiān.","vi":"Hôm qua âm u, hôm nay nắng.","en":"Yesterday was cloudy, today is sunny."}]},"虽然":{"en":"although; though","exs":[{"use":"虽然……，但是…….","ex":"虽然很累，但是我很高兴。","py":"Suīrán hěn lèi, dànshì wǒ hěn gāoxìng.","vi":"Tuy mệt nhưng tôi rất vui.","en":"Although I'm tired, I'm happy."},{"use":"虽然 đứng sau chủ ngữ hoặc đầu câu.","ex":"他虽然年轻，但是很有经验。","py":"Tā suīrán niánqīng, dànshì hěn yǒu jīngyàn.","vi":"Anh ấy tuy trẻ nhưng rất có kinh nghiệm.","en":"Though young, he is very experienced."},{"use":"Có thể bỏ 但是 nhưng dùng 可是/却 sau.","ex":"虽然下雨，我们还是去了。","py":"Suīrán xià yǔ, wǒmen háishi qù le.","vi":"Tuy mưa nhưng chúng tôi vẫn đi.","en":"Although it rained, we still went."}]},"玩儿":{"en":"to play; to have fun","exs":[{"use":"玩儿 + N: chơi cái gì.","ex":"孩子们在公园玩儿。","py":"Háizimen zài gōngyuán wánr.","vi":"Bọn trẻ chơi ở công viên.","en":"The children are playing in the park."},{"use":"去 + 地方 + 玩儿.","ex":"周末我们去海边玩儿。","py":"Zhōumò wǒmen qù hǎibiān wánr.","vi":"Cuối tuần chúng tôi ra biển chơi.","en":"We go to the beach on weekends."},{"use":"玩儿得 + 开心.","ex":"你玩儿得开心吗？","py":"Nǐ wánr de kāixīn ma?","vi":"Bạn chơi có vui không?","en":"Did you have fun?"}]},"有意思":{"en":"interesting; fun","exs":[{"use":"很有意思: rất thú vị.","ex":"这个电影很有意思。","py":"Zhège diànyǐng hěn yǒu yìsi.","vi":"Bộ phim này rất thú vị.","en":"This movie is very interesting."},{"use":"有意思 + 的 + N.","ex":"他给我讲了一个有意思的故事。","py":"Tā gěi wǒ jiǎng le yí ge yǒu yìsi de gùshi.","vi":"Anh ấy kể cho tôi một câu chuyện thú vị.","en":"He told me an interesting story."},{"use":"没意思: chán.","ex":"这本书没意思。","py":"Zhè běn shū méi yìsi.","vi":"Quyển sách này chán.","en":"This book is boring."}]},"大家":{"en":"everyone; all","exs":[{"use":"大家 + 都: mọi người đều.","ex":"大家都来了。","py":"Dàjiā dōu lái le.","vi":"Mọi người đều đến rồi.","en":"Everyone has come."},{"use":"Dùng để gọi cả nhóm.","ex":"大家好！","py":"Dàjiā hǎo!","vi":"Chào mọi người!","en":"Hello, everyone!"},{"use":"大家 + 一起.","ex":"大家一起唱歌吧。","py":"Dàjiā yìqǐ chàng gē ba.","vi":"Mọi người cùng hát nào.","en":"Let's all sing together."}]},"火车站":{"en":"railway station","exs":[{"use":"去火车站.","ex":"我们去火车站接朋友。","py":"Wǒmen qù huǒchēzhàn jiē péngyou.","vi":"Chúng tôi ra ga đón bạn.","en":"We go to the station to meet a friend."},{"use":"火车站 + 离 + 这儿 + 远.","ex":"火车站离这儿不远。","py":"Huǒchēzhàn lí zhèr bù yuǎn.","vi":"Ga tàu cách đây không xa.","en":"The station isn't far from here."},{"use":"在火车站 + 买票.","ex":"他在火车站买了两张票。","py":"Tā zài huǒchēzhàn mǎi le liǎng zhāng piào.","vi":"Anh ấy mua hai vé ở ga.","en":"He bought two tickets at the station."}]},"妹妹":{"en":"younger sister","exs":[{"use":"Gọi em gái ruột.","ex":"我妹妹在上大学。","py":"Wǒ mèimei zài shàng dàxué.","vi":"Em gái tôi đang học đại học.","en":"My younger sister is in college."},{"use":"妹妹 + 比 + 我 + 小.","ex":"妹妹比我小两岁。","py":"Mèimei bǐ wǒ xiǎo liǎng suì.","vi":"Em gái kém tôi hai tuổi.","en":"My sister is two years younger than me."},{"use":"妹妹 + 来了.","ex":"你妹妹还没到吗？","py":"Nǐ mèimei hái méi dào ma?","vi":"Em gái bạn vẫn chưa đến à?","en":"Hasn't your sister arrived yet?"}]},"票":{"en":"ticket","exs":[{"use":"Lượng từ: 一张票.","ex":"我买了两张火车票。","py":"Wǒ mǎi le liǎng zhāng huǒchē piào.","vi":"Tôi mua hai vé tàu.","en":"I bought two train tickets."},{"use":"买票/订票.","ex":"请先去买票。","py":"Qǐng xiān qù mǎi piào.","vi":"Xin hãy đi mua vé trước.","en":"Please buy a ticket first."},{"use":"票 + 多少钱.","ex":"电影票多少钱一张？","py":"Diànyǐng piào duōshao qián yì zhāng?","vi":"Vé xem phim bao nhiêu một tờ?","en":"How much is a movie ticket?"}]},"日":{"en":"day; date","exs":[{"use":"Dùng trong ngày tháng trang trọng (号 là khẩu ngữ).","ex":"今天是五月一日。","py":"Jīntiān shì wǔ yuè yī rì.","vi":"Hôm nay là ngày một tháng năm.","en":"Today is May 1st."},{"use":"生日: ngày sinh.","ex":"祝你生日快乐！","py":"Zhù nǐ shēngrì kuàilè!","vi":"Chúc bạn sinh nhật vui vẻ!","en":"Happy birthday!"},{"use":"日 + 子: ngày tháng.","ex":"新年是一个快乐的日子。","py":"Xīnnián shì yí ge kuàilè de rìzi.","vi":"Năm mới là một ngày vui.","en":"New Year is a happy day."}]},"阴":{"en":"overcast; cloudy","exs":[{"use":"阴天: trời âm u.","ex":"今天是阴天。","py":"Jīntiān shì yīntiān.","vi":"Hôm nay trời âm u.","en":"Today is overcast."},{"use":"天 + 阴 + 了: trời đã u ám.","ex":"天阴了，快下雨了。","py":"Tiān yīn le, kuài xià yǔ le.","vi":"Trời u ám rồi, sắp mưa.","en":"It's clouding over; rain is coming."},{"use":"阴 + 的 + 天气.","ex":"阴的天气让人想睡觉。","py":"Yīn de tiānqì ràng rén xiǎng shuì jiào.","vi":"Trời âm u khiến người ta buồn ngủ.","en":"Gloomy weather makes you sleepy."}]},"更":{"en":"more; even more","exs":[{"use":"更 + adj: còn hơn.","ex":"今天比昨天更冷。","py":"Jīntiān bǐ zuótiān gèng lěng.","vi":"Hôm nay lạnh hơn hôm qua.","en":"Today is even colder than yesterday."},{"use":"更 + V (tâm lý).","ex":"我更喜欢这个。","py":"Wǒ gèng xǐhuan zhège.","vi":"Tôi thích cái này hơn.","en":"I like this one even more."},{"use":"更 + 好/快.","ex":"我们要更努力学习。","py":"Wǒmen yào gèng nǔlì xuéxí.","vi":"Chúng ta phải học chăm hơn nữa.","en":"We should study even harder."}]},"新年":{"en":"New Year","exs":[{"use":"新年快乐: chúc mừng năm mới.","ex":"祝你新年快乐！","py":"Zhù nǐ xīnnián kuàilè!","vi":"Chúc bạn năm mới vui vẻ!","en":"Happy New Year!"},{"use":"新年 + 就要到了: sắp đến năm mới.","ex":"新年就要到了。","py":"Xīnnián jiù yào dào le.","vi":"Năm mới sắp đến rồi.","en":"The New Year is coming."},{"use":"过新年.","ex":"中国人在新年的时候回家。","py":"Zhōngguó rén zài xīnnián de shíhou huí jiā.","vi":"Người Trung Quốc về nhà vào dịp năm mới.","en":"Chinese people go home at the New Year."}]}});
